function getCompactRelation(world, a, b) {
  // Authored pair relations win over the generic catch-alls below: this table is
  // how the zoo states a DIRECT relationship for pairs that would otherwise fall
  // through to "Near miss".
  const keyed = (COMPACT_PAIR_RELATIONS[world.id] || {})[getCompactEdgeId(a, b)];
  if (keyed) {
    return compactRelation(
      keyed.type, keyed.kind, keyed.summary, keyed.route, keyed.takeaway,
      keyed.caveat, keyed.steps || [], keyed.signal || '↔'
    );
  }

  const ids = new Set([a.id, b.id]);
  const has = (id) => ids.has(id);
  const hasAny = (items) => items.some((id) => ids.has(id));

  if (world.id === 'general') {
    if (has('open-cover') && has('fip')) {
      return compactRelation(
        'Complement duality',
        'compact-equivalent',
        'Open covers and closed-set intersections are the same statement with complements reversed.',
        'open cover -> complements -> finite intersection property',
        'Covers say “these opens miss nothing”; FIP says “these closed constraints still meet.” Compactness makes those equivalent.',
        'Works in arbitrary topological spaces.',
        [
          'Assume a family of closed sets has the finite intersection property but empty total intersection.',
          'Take complements. Those complements form an open cover of X.',
          'A finite subcover would translate back to a finite closed subfamily with empty intersection, contradicting FIP.',
        ],
        '↔',
        [
          {
            from: 'left',
            to: 'right',
            role: 'duality',
            symbol: '∵',
            title: 'Open-cover compactness gives FIP',
            summary:
              'The proof is by contradiction: an empty total closed intersection becomes an open cover by complements.',
            steps: [
              'Assume X is open-cover compact and {F_i} is a closed family with the finite intersection property.',
              'If the total intersection were empty, then {X \\ F_i} would be an open cover of X.',
              'Compactness gives finitely many complements covering X, so the corresponding finite closed intersection is empty, contradicting FIP.',
            ],
          },
          {
            from: 'right',
            to: 'left',
            role: 'duality',
            symbol: '∴',
            title: 'FIP gives open-cover compactness',
            summary:
              'Run the same complement switch backward: a cover with no finite subcover creates closed sets with FIP.',
            steps: [
              'Assume every closed family with FIP has nonempty total intersection.',
              'Let {U_i} be an open cover with no finite subcover; then the closed sets X \\ U_i have the finite intersection property.',
              'FIP gives a point in every X \\ U_i, meaning a point outside every U_i, contradicting that {U_i} covers X.',
            ],
          },
        ]
      );
    }
    if (has('open-cover') && has('basis-cover')) {
      return compactRelation(
        'Basis refinement',
        'compact-equivalent',
        'Basis covers are enough because every open cover can be refined by basis elements.',
        'arbitrary open cover -> basis refinement -> finite basis subcover -> original finite subcover',
        'The topology can be tested through any honest basis, which keeps many compactness proofs small.',
        'Works for a fixed basis of the topology.',
        [
          'Start with an arbitrary open cover and choose, around each point, a basis element sitting inside one cover member.',
          'The chosen basis elements cover X, so the basis-cover test gives finitely many of them.',
          'Replace each selected basis element by the original open set that contained it.',
        ],
        '↔',
        [
          {
            from: 'left',
            to: 'right',
            role: 'trivial',
            symbol: '∴',
            title: 'Open-cover compactness gives the basis-cover test',
            summary:
              'This direction is immediate: a cover by basis elements is still an open cover.',
            steps: [
              'Assume every open cover of X has a finite subcover.',
              'Let B be a cover of X by basis elements; each basis element is open.',
              'Therefore B is an open cover, so it has a finite subcover.',
            ],
          },
          {
            from: 'right',
            to: 'left',
            role: 'construction',
            symbol: '∵',
            title: 'Basis-cover test gives open-cover compactness',
            summary:
              'This direction does the real work: refine an arbitrary open cover to a basis cover, then lift the finite basis subcover back to the original cover.',
            steps: [
              'Assume every basis cover of X has a finite subcover, and let U be an arbitrary open cover.',
              'For each x in X, choose U_x in U with x in U_x, then choose a basis element B_x with x in B_x subset U_x.',
              'The B_x form a basis cover, so finitely many B_x1, ..., B_xn cover X; the corresponding U_x1, ..., U_xn are a finite subcover of the original U.',
            ],
          },
        ]
      );
    }
    if (has('subbase') && (has('open-cover') || has('basis-cover'))) {
      return compactRelation(
        'Alexander bridge',
        'compact-equivalent',
        'Alexander subbase theorem reduces the cover test to subbasic covers.',
        'subbasic cover -> maximal cover argument -> open-cover compactness',
        'The full topology can be tested through its generating opens, which is wonderfully efficient.',
        'Works for a chosen subbase in arbitrary topological spaces; the theorem itself is equivalent to the ultrafilter lemma (BPI) over ZF and is not provable in ZF alone.',
        [
          'Assume a subbasic-cover test succeeds but some ordinary open cover has no finite subcover.',
          'Use a maximal-cover argument to enlarge that bad cover while keeping it bad.',
          'The maximal bad cover must contain enough subbasic sets to become a bad subbasic cover, contradiction.',
        ]
      );
    }
    if (has('tychonoff')) {
      return compactRelation(
        'Tychonoff product',
        'compact-scope',
        'Arbitrary products of compact spaces are compact; the cleanest proofs run through the Alexander subbase test or coordinatewise ultrafilter convergence.',
        'subbasic boxes -> Alexander subbase -> compact product; or every ultrafilter converges coordinatewise',
        'Compactness is exactly the property closed under arbitrary products, the engine behind Stone–Čech and function-space compactness.',
        'For arbitrary index sets Tychonoff is equivalent to the axiom of choice (Kelley); the proof via the Alexander subbase theorem or ultrafilters uses the ultrafilter lemma (BPI), and the box topology breaks the theorem.',
        [
          'A subbase for the product topology is the family of single-coordinate restrictions (preimages of opens under one projection).',
          'By the Alexander subbase theorem it suffices that every cover by such subbasic sets has a finite subcover; coordinatewise compactness supplies it.',
          'Equivalently, an ultrafilter on the product pushes to an ultrafilter in each compact factor, which converges; the coordinatewise limits give a limit in the product.',
        ],
        '∏ →'
      );
    }
    if (hasAny(['net', 'filter', 'ultrafilter']) && ids.size === 2 && [...ids].every((id) => ['net', 'filter', 'ultrafilter'].includes(id))) {
      return compactRelation(
        'Generalized convergence',
        'compact-equivalent',
        'Nets, filters, and ultrafilters are three languages for convergence beyond sequences.',
        'directed tails <-> filter bases <-> maximal filters',
        'They are different instruments for detecting the same “nothing escapes” compactness behavior.',
        'No Hausdorff assumption is needed, though limits may not be unique; the convergence-implies-compact direction relies on the ultrafilter lemma (BPI), a weak choice principle, not ZF alone.',
        [
          'A net has tails; those tails generate a filter describing where the net is eventually forced to live.',
          'A filter can be represented by a directed system of choices, which behaves like a net.',
          'Ultrafilters are maximal filters, so proving convergence for them controls all smaller filter behavior by extension.',
        ]
      );
    }
    if (hasAny(['net', 'filter', 'ultrafilter']) && has('open-cover')) {
      return compactRelation(
        'No escaping tail',
        'compact-equivalent',
        'Open-cover compactness is equivalent to the claim that every generalized trajectory has somewhere to accumulate.',
        'bad cover -> escaping net/filter; cluster point -> finite obstruction',
        'A failed finite subcover lets you build a generalized object that keeps avoiding every proposed landing zone.',
        'Sequences alone are too narrow for this argument in arbitrary spaces.',
        [
          'If an open cover has no finite subcover, direct the finite subfamilies by inclusion.',
          'Choose a point outside each finite union. These choices form a net that cannot cluster inside any cover member.',
          'Conversely, compactness plus FIP forces the closed tails of any net or filter to meet, producing a cluster point.',
        ]
      );
    }
    if (has('projection')) {
      return compactRelation(
        'Closed projection',
        'compact-equivalent',
        'Compactness is exactly what lets projection preserve closed sets across every product X x Y.',
        'compact fibers -> tube-style finite choice -> closed projection',
        'This makes compactness feel like a stable behavior under forgetting coordinates.',
        'The theorem characterizes compactness when the projection is closed for every target space Y.',
        [
          'To prove closedness, take a point y outside the projected image of a closed set C in Y x X.',
          'Each x in X has a product neighborhood avoiding C near (y, x).',
          'Compactness extracts finitely many x-neighborhoods, and their matching y-neighborhoods intersect to keep y outside the projection.',
        ]
      );
    }
    return compactRelation(
      'Definition hub',
      'compact-equivalent',
      'This edge routes through open-cover compactness, the usual hub for the general theory.',
      `${a.title} -> open-cover compactness -> ${b.title}`,
      'The complete graph is deliberately dense here: every formulation can be translated to the cover definition and then out again.',
      'Works in arbitrary topological spaces for the definitions in this world.',
      [
        `Translate ${a.title} into the open-cover formulation.`,
        'Use the open-cover version as the common compactness hub.',
        `Translate the hub statement into ${b.title}.`,
      ]
    );
  }

  if (world.id === 'metric') {
    if (has('heine-borel') && has('bolzano-weierstrass')) {
      return compactRelation(
        'Euclidean sequence theorem',
        'compact-equivalent',
        'In R^n, closed-and-bounded compactness and Bolzano-Weierstrass sequential compactness are two faces of the same finite-dimensional theorem.',
        'closed + bounded <-> every sequence has a convergent subsequence landing in A',
        'Boundedness gives subsequential limits in R^n, and closedness keeps those limits inside the set.',
        'This is a finite-dimensional Euclidean theorem.',
        [
          'Boundedness places every sequence inside a large Euclidean box.',
          'Bolzano-Weierstrass extracts a convergent subsequence in R^n.',
          'Closedness of A guarantees the subsequential limit still belongs to A.',
        ]
      );
    }
    if (has('heine-borel') || has('bolzano-weierstrass')) {
      return compactRelation(
        'Euclidean specialization',
        'compact-scope',
        'The Euclidean criteria are equivalent to compactness inside R^n because finite-dimensional Euclidean geometry supplies total boundedness and closed-set completeness.',
        'R^n structure -> complete + totally bounded -> compact',
        'The familiar calculus test is not the general metric theorem; it is the Euclidean costume of the metric theorem.',
        'Closed and bounded is not enough in every metric space.',
        [
          'In R^n, bounded sets are totally bounded: finitely many small boxes or balls cover them at every scale.',
          'Closed subsets of complete R^n are complete.',
          'Complete plus totally bounded gives metric compactness, and compact subsets of R^n are closed and bounded.',
        ],
        'R^n ↔'
      );
    }
    if (has('complete-totally-bounded') && has('precompact-complete')) {
      return compactRelation(
        'Completion language',
        'compact-equivalent',
        'Total boundedness says the completion is compact after holes are filled; completeness says no holes were missing.',
        'total bounded <-> compact completion; complete -> X equals its completion',
        'Precompactness is total boundedness viewed from the completed space.',
        'This depends on metric or uniform structure.',
        [
          'A totally bounded metric space has a totally bounded completion.',
          'A complete totally bounded metric space is compact by the sequence/Cauchy argument.',
          'If X is already complete, the compact completion is just X.',
        ]
      );
    }
    if (has('complete-totally-bounded') && has('cauchy-subsequence')) {
      return compactRelation(
        'Cauchy extraction',
        'compact-equivalent',
        'Total boundedness extracts Cauchy subsequences, and completeness turns Cauchy behavior into convergence.',
        'finite epsilon-nets -> Cauchy subsequence -> complete limit',
        'Metric compactness is “small at every scale” plus “no missing limits.”',
        'This is a metric-space equivalence.',
        [
          'Cover X by finitely many 1-balls; infinitely many sequence terms land in one ball.',
          'Inside that ball, cover by finitely many 1/2-balls, then 1/3-balls, and continue diagonally.',
          'The nested choices give a Cauchy subsequence, and completeness supplies its limit in X.',
        ]
      );
    }
    if (has('metric-cover') && has('complete-totally-bounded')) {
      return compactRelation(
        'Metric compactness theorem',
        'compact-equivalent',
        'Open-cover compactness is equivalent to completeness plus total boundedness in metric spaces.',
        'open covers <-> sequential compactness <-> complete + totally bounded',
        'The cover definition becomes a concrete test: finite epsilon-nets at every scale, with all Cauchy limits retained.',
        'This is the main metric-space theorem. The uniform-space version replaces epsilon-balls by entourages.',
        [
          'Compactness gives total boundedness by applying finite subcovers to epsilon-ball covers.',
          'Compactness gives completeness because every Cauchy sequence has a cluster point, hence converges to it.',
          'Complete plus total bounded gives convergent subsequences for every sequence, and metric sequential compactness gives open-cover compactness.',
        ]
      );
    }
    if (has('metric-cover') && has('sequential')) {
      return compactRelation(
        'Sequence-cover equivalence',
        'compact-equivalent',
        'Metric spaces let cover failures be encoded as sequences, so sequential compactness and open-cover compactness coincide.',
        'bad cover -> no Lebesgue scale -> escaping sequence',
        'A metric turns “no finite subcover” into a countable process you can chase with points.',
        'This shortcut is the one that fails most visibly outside metric spaces.',
        [
          'If compactness fails, construct a sequence that stays outside every attempted finite cover witness.',
          'Sequential compactness gives a convergent subsequence.',
          'The open set covering the limit eventually catches that subsequence, contradicting the construction.',
        ]
      );
    }
    if (has('sequential') && (has('limit-point') || has('countably-compact'))) {
      return compactRelation(
        'Countable local bases',
        'compact-equivalent',
        'Metric balls convert countable cover failures, infinite subsets, and sequence failures into one another.',
        'countable balls -> sequence or infinite set -> convergent subsequence',
        'The metric gives enough countability for sequences to carry the compactness story.',
        'This equivalence can fail outside first-countable or metric settings.',
        [
          'A sequence without a convergent subsequence gives an infinite set with no accumulation behavior.',
          'An infinite set with no accumulation point can be separated by countably organized metric balls.',
          'A countable cover with no finite subcover lets you choose a sequence escaping the first n cover sets.',
        ]
      );
    }
    if (has('precompact-complete') && hasAny(['cauchy-subsequence', 'sequential'])) {
      return compactRelation(
        'Filled completion',
        'compact-equivalent',
        'Precompactness supplies Cauchy subsequences; completeness makes their limits live in X.',
        'compact completion + complete -> convergent subsequences',
        'Completion language is often the cleanest way to remember what total boundedness is buying.',
        'Precompact without complete is only “almost compact.”',
        [
          'Precompactness means every sequence has a Cauchy subsequence after passing to the completion.',
          'Completeness says that subsequence limit is already a point of X.',
          'Thus every sequence has a convergent subsequence in X.',
        ]
      );
    }
    return compactRelation(
      'Sequential route',
      'compact-equivalent',
      'This edge routes through sequential compactness, the easiest metric hub.',
      `${a.title} -> sequential compactness -> ${b.title}`,
      'In metric spaces, compactness can be tested by the behavior of sequences.',
      'The sequence shortcut is not valid in arbitrary topological spaces.',
      [
        `Translate ${a.title} into a statement about sequences or Cauchy subsequences.`,
        'Use metric sequential compactness as the hub.',
        `Translate sequential compactness into ${b.title}.`,
      ]
    );
  }

  if (world.id === 'variants') {
    if (has('lindelof-variant') && has('countably-compact-variant')) {
      return compactRelation(
        'Two-step compactness recipe',
        'compact-implies',
        'Lindelöf plus countably compact recovers compactness: arbitrary covers become countable, then finite.',
        'open cover -> countable subcover -> finite subcover',
        'This is a useful way to see exactly what each weakened cover condition contributes.',
        'Neither condition alone is compactness.',
        [
          'Start with an arbitrary open cover.',
          'Lindelöfness reduces it to a countable subcover.',
          'Countable compactness reduces that countable subcover to a finite subcover.',
        ],
        'L + ω -> K'
      );
    }
    if (has('compact-baseline')) {
      const other = a.id === 'compact-baseline' ? b : a;
      if (other.id === 'sequential-variant') {
        return compactRelation(
          'Metric reunion',
          'compact-scope',
          'Sequential compactness equals compactness in metric spaces, but the two split in general topology.',
          'general: split; metric: compact <-> sequentially compact',
          'Sequences are superb in metric spaces because countable balls see the topology; arbitrary spaces need nets or filters.',
          'Do not replace compactness by sequential compactness without checking the ambient hypotheses.',
          [
            'In metric spaces, a bad cover can be turned into a sequence with no convergent subsequence.',
            'In arbitrary spaces, sequences may not detect all closure or cover behavior.',
            'Nets and filters repair that gap.',
          ],
          'metric ↔'
        );
      }
      if (other.id === 'countably-compact-variant') {
        return compactRelation(
          'Countable shadow',
          'compact-implies',
          'Compactness implies countable compactness, but the converse needs a way to shrink arbitrary covers to countable covers.',
          'compact -> countably compact; Lindelöf + countably compact -> compact',
          'Countably compact is the cover definition with the arbitrary part removed.',
          'The converse is false without extra hypotheses.',
          [
            'Every countable open cover is an open cover, so compactness makes it finite.',
            'If a space is also Lindelöf, every open cover has a countable subcover.',
            'Then countable compactness finishes the finite-subcover step.',
          ],
          'K -> ω'
        );
      }
      if (other.id === 'limit-point-variant') {
        return compactRelation(
          'Accumulation shadow',
          'compact-scope',
          'In any topological space, compactness forces every infinite subset to accumulate (no separation axiom needed); in metric spaces limit point compactness becomes equivalent to compactness.',
          'compact -> limit point compact (any space); metric: limit-point compact <-> compact',
          'Limit points are a point-set way of watching infinity fail to disperse.',
          'The forward implication needs no separation axiom; T1/first-countability is needed only for the reverse-leaning facts (limit-point compact + T1 -> countably compact; the metric chain runs limit-point compact -> countably compact -> sequentially compact -> compact).',
          [
            'If an infinite subset had no accumulation point in a compact space (no T1 needed), each of its points would get a neighborhood meeting the subset only at itself.',
            'Those neighborhoods, together with the complement of the now-closed subset, form an open cover with no finite subcover.',
            'Metric spaces turn this obstruction into the sequential compactness theorem.',
          ],
          'scope'
        );
      }
      if (other.id === 'lindelof-variant') {
        return compactRelation(
          'Countable cover shadow',
          'compact-implies',
          'Compactness implies Lindelöfness because finite subcovers are automatically countable.',
          'compact -> finite subcover -> countable subcover',
          'Lindelöfness controls cover size, not finite capture.',
          'R is Lindelöf but not compact.',
          [
            'Take any open cover of a compact space.',
            'Compactness gives a finite subcover.',
            'Every finite subcover is countable, so the space is Lindelöf.',
          ],
          'K -> L'
        );
      }
      if (other.id === 'precompact-variant') {
        return compactRelation(
          'Scale shadow',
          'compact-scope',
          'Compact metric spaces are totally bounded, but total boundedness alone only says the space is compact after completing the missing limits.',
          'compact metric -> totally bounded; complete + totally bounded -> compact',
          'Total boundedness is the “small at every scale” half of metric compactness.',
          'This property depends on metric or uniform structure, not just topology.',
          [
            'Cover a compact metric space by epsilon-balls and take a finite subcover.',
            'That finite subcover is exactly a finite epsilon-net.',
            'To reverse the implication, add completeness so Cauchy limits cannot escape.',
          ],
          'K -> ε'
        );
      }
      if (other.id === 'pseudocompact-variant') {
        return compactRelation(
          'Function-bound shadow',
          'compact-implies',
          'Compactness implies pseudocompactness because continuous real-valued images of compact spaces are compact, hence bounded.',
          'compact X -> compact f(X) subset R -> bounded f(X)',
          'Pseudocompactness tests the space through real-valued measurements rather than covers.',
          'The converse is false in common completely regular settings.',
          [
            'Let f:X -> R be continuous.',
            'If X is compact, f(X) is compact in R.',
            'Compact subsets of R are closed and bounded, so f is bounded.',
          ],
          'K -> f'
        );
      }
      if (other.id === 'locally-compact-variant') {
        return compactRelation(
          'Local-global split',
          'compact-implies',
          'Compact Hausdorff spaces are locally compact, but local compactness only controls neighborhoods, not the whole space.',
          'compact neighborhood at each point; no global finite cover guarantee',
          'Local compactness says every point has a compact window, while compactness says one finite collection of windows can catch everything.',
          'Definitions vary slightly outside Hausdorff spaces.',
          [
            'In a compact space, the whole space can serve as a compact neighborhood in the broad convention.',
            'In compact Hausdorff spaces, points also have well-behaved compact neighborhood structure.',
            'Noncompact examples such as R^n show the local condition does not force global compactness.',
          ],
          'K -> loc'
        );
      }
      if (other.id === 'sigma-compact-variant') {
        return compactRelation(
          'Exhaustion shadow',
          'compact-implies',
          'Compactness implies sigma-compactness, but a countable union of compact pieces can still drift outward forever.',
          'compact -> one compact piece; sigma-compact -> countable compact exhaustion',
          'Sigma-compactness is a useful exhaustion property, not a finite-subcover property.',
          'R^n is sigma-compact but not compact.',
          [
            'A compact space is sigma-compact by taking K_1 = X.',
            'A sigma-compact space allows X to be covered by K_1, K_2, K_3, and so on.',
            'The countable list need not collapse to one compact piece or a finite cover.',
          ],
          'K -> σ'
        );
      }
      if (other.id === 'continuous-image-variant') {
        return compactRelation(
          'Continuous image / EVT',
          'compact-implies',
          'Compactness is preserved by continuous maps, so a continuous image of a compact space is compact; over R this is the extreme value theorem.',
          'compact X -> continuous f(X) compact -> closed & bounded in R -> max/min attained',
          'This is why optimization on a compact set always has a solution, and why a continuous bijection from compact to Hausdorff is a homeomorphism.',
          'One-way: compactness implies these, but they do not characterize it. The EVT specialization needs the target to be R (or an ordered space); the homeomorphism corollary needs the target Hausdorff.',
          [
            'Take an open cover of f(X); pulling back through the continuous f gives an open cover of X.',
            'Compactness of X yields a finite subcover, whose images form a finite subcover of f(X), so f(X) is compact.',
            'For f:X -> R, the compact image f(X) is closed and bounded, so sup and inf belong to f(X) and are attained.',
          ],
          'K -> f(K)'
        );
      }
    }
    if (has('sequential-variant') && has('countably-compact-variant')) {
      return compactRelation(
        'Sequential ⇒ countable',
        'compact-implies',
        'Sequentially compact implies countably compact in EVERY topological space; the reverse needs first-countability (e.g. metric).',
        'extract a convergent subsequence -> no infinite closed discrete set',
        'The forward arrow is unconditional; only the converse is metric/first-countable.',
        'One-way in general: countably compact ⇒ sequentially compact requires first-countability. All these probes coincide in metric/first-countable spaces.',
        [
          'A sequentially compact space has a convergent subsequence for every sequence.',
          'That forbids a countable open cover with no finite subcover, so it is countably compact.',
          'The reverse direction can fail without a countable local base.',
        ],
        'seq → ω'
      );
    }
    if (has('countably-compact-variant') && has('limit-point-variant')) {
      return compactRelation(
        'Countable ⇒ limit-point',
        'compact-implies',
        'Countably compact implies limit-point compact in EVERY topological space (no separation axiom); the reverse needs T1.',
        'countable cover failure -> accumulation point of any infinite set',
        'The forward arrow holds unconditionally; the converse limit-point ⇒ countably compact needs T1.',
        'One-way in general: limit-point compact ⇒ countably compact requires T1. All these probes coincide in metric/first-countable spaces.',
        [
          'In a countably compact space every infinite subset has an accumulation point.',
          'So the space is limit-point compact with no separation hypothesis.',
          'Recovering countable compactness from limit-point compactness needs T1.',
        ],
        'ω → acc'
      );
    }
    if (has('sequential-variant') && has('limit-point-variant')) {
      return compactRelation(
        'Sequential ⇒ limit-point',
        'compact-implies',
        'Sequentially compact implies limit-point compact unconditionally (via the seq ⇒ ω ⇒ acc chain); the reverse needs first-countability.',
        'convergent subsequence -> accumulation point of any infinite set',
        'The forward arrow is unconditional; the converse is the first-countable case.',
        'One-way in general; the reverse direction needs first-countability. All these probes coincide in metric/first-countable spaces.',
        [
          'A convergent subsequence supplies an accumulation point for any infinite set.',
          'So sequential compactness forces limit-point compactness with no extra axiom.',
          'The reverse holds only with a countable local base.',
        ],
        'seq → acc'
      );
    }
    if (has('precompact-variant')) {
      return compactRelation(
        'Structure-dependent cousin',
        'compact-scope',
        'Precompactness and total boundedness belong to metric or uniform spaces, so they compare to topological compactness only after the structure is fixed.',
        'finite epsilon-nets + completeness -> compactness',
        'This is the main answer to the “totally bounded” memory: it is compactness with a metric-scale lens attached.',
        'A bare topological space has no epsilon-balls, so it has no total boundedness until extra structure is chosen.',
        [
          'Choose a metric or uniformity.',
          'Ask for finite nets at every scale.',
          'Add completeness if you want actual compactness rather than compactness after completion.',
        ],
        'scope'
      );
    }
    return compactRelation(
      'Near miss',
      'compact-warning',
      'These properties are compactness-adjacent, but neither one should be silently substituted for the other.',
      `${a.title} compared with ${b.title}`,
      'The lesson here is hypothesis awareness: the same word “compact” can be cover-theoretic, sequential, local, functional, or metric-scale flavored.',
      'Use the green metric/general worlds when you need genuine equivalences.',
      [
        'Identify which kind of data the property controls: covers, sequences, functions, local neighborhoods, or metric scales.',
        'Check whether the theorem assumes metric, Hausdorff, T1, Lindelöf, or completeness hypotheses.',
        'Only then decide whether the edge is an implication, an equivalence, or just an analogy.',
      ],
      '!'
    );
  }

  return compactRelation(
    'Definition bridge',
    'compact-scope',
    'This pair belongs to a compactness world without a specialized bridge.',
    `${a.title} -> compactness context -> ${b.title}`,
    'Check the active world label and scope note before using the relation.',
    'No additional specialization is encoded for this edge.',
    [
      'Read both definitions carefully.',
      'Route through the world note.',
      'Apply only the hypotheses stated in this panel.',
    ],
    'scope'
  );
}

function compactRelation(type, kind, summary, route, takeaway, caveat, steps = [], signal = '↔', directions = []) {
  return { type, kind, summary, route, takeaway, caveat, steps, signal, directions };
}

