function compactBridgeLabelLines(label, maxLines = 2, maxChars = 14) {
  const compact = label
    .replace(' compactness', '')
    .replace(' theorem', '')
    .replace(' in R^n', '');
  const words = compact.split(/\s+/).filter(Boolean);
  const lines = [];
  let current = '';

  for (const word of words) {
    const next = current ? `${current} ${word}` : word;
    if (next.length <= maxChars) {
      current = next;
      continue;
    }
    if (current) lines.push(current);
    current = word.length > maxChars ? `${word.slice(0, maxChars - 3)}...` : word;
    if (lines.length === maxLines - 1) break;
  }

  if (lines.length < maxLines && current) lines.push(current);
  if (words.join(' ').length > lines.join(' ').length && lines.length) {
    const last = lines.length - 1;
    lines[last] = lines[last].length > maxChars - 3 ? `${lines[last].slice(0, maxChars - 3)}...` : `${lines[last]}...`;
  }
  return lines.length ? lines : [compactShortLabel(label)];
}

function renderCompactBridgeLabel(label, x, y, className) {
  const lines = compactBridgeLabelLines(label);
  return `
    <text class="compact-bridge-title ${className}" x="${x}" y="${y}" text-anchor="middle">
      ${lines
        .map((line, index) => `<tspan x="${x}" dy="${index === 0 ? 0 : 17}">${line}</tspan>`)
        .join('')}
    </text>
  `;
}

function compactBridgeArrowHead(tip, tangent, color) {
  const length = 15;
  const width = 12;
  const norm = Math.hypot(tangent.x, tangent.y) || 1;
  const unit = { x: tangent.x / norm, y: tangent.y / norm };
  const perp = { x: -unit.y, y: unit.x };
  const base = {
    x: tip.x - unit.x * length,
    y: tip.y - unit.y * length,
  };
  const left = {
    x: base.x + perp.x * width * 0.5,
    y: base.y + perp.y * width * 0.5,
  };
  const right = {
    x: base.x - perp.x * width * 0.5,
    y: base.y - perp.y * width * 0.5,
  };
  return `
    <path
      class="compact-bridge-arrowhead"
      d="M ${tip.x} ${tip.y} L ${left.x.toFixed(1)} ${left.y.toFixed(1)} Q ${base.x.toFixed(1)} ${base.y.toFixed(1)} ${right.x.toFixed(1)} ${right.y.toFixed(1)} Z"
      fill="${color}"
    />
  `;
}

function renderCompactBridgeDemo(relation, a, b) {
  const directions = relation.directions || [];
  const forward = directions.find((direction) => direction.from === 'left' && direction.to === 'right');
  const backward = directions.find((direction) => direction.from === 'right' && direction.to === 'left');
  const arrowMode = getCompactArrowMode(relation);
  const showsBackward = Boolean(backward || arrowMode === 'both' || arrowMode === 'backward');
  const forwardRole = compactProofRoleLabel(forward?.role || 'lemma');
  const backwardRole = compactProofRoleLabel(backward?.role || 'lemma');
  return `
    <div class="compact-demo-title">${relation.type}</div>
    <svg class="compact-demo-svg" viewBox="0 0 360 240" role="img" aria-label="Compactness proof bridge">
      <rect class="compact-bridge-box left" x="22" y="72" width="122" height="86" rx="20" />
      <rect class="compact-bridge-box right" x="216" y="72" width="122" height="86" rx="20" />
      <path class="compact-bridge-arrow forward ${forward?.role === 'trivial' ? 'trivial' : ''}" d="M144 86 C160 54 200 54 216 86" />
      ${compactBridgeArrowHead({ x: 216, y: 86 }, { x: 16, y: 32 }, '#2c7ab3')}
      ${
        showsBackward
          ? `<path class="compact-bridge-arrow backward ${backward?.role === 'trivial' ? 'trivial' : ''}" d="M216 144 C200 176 160 176 144 144" />
             ${compactBridgeArrowHead({ x: 144, y: 144 }, { x: -16, y: -32 }, '#c9532a')}`
          : '<path class="compact-bridge-arrow backward muted" d="M216 144 C200 176 160 176 144 144" />'
      }
      <text class="compact-bridge-side left" x="83" y="96" text-anchor="middle">left</text>
      <text class="compact-bridge-side right" x="277" y="96" text-anchor="middle">right</text>
      ${renderCompactBridgeLabel(a.title, 83, 124, 'left')}
      ${renderCompactBridgeLabel(b.title, 277, 124, 'right')}
      <text class="compact-bridge-proof forward" x="180" y="52" text-anchor="middle">${forward?.symbol || '∴'} ${forwardRole}</text>
      <text class="compact-bridge-proof backward" x="180" y="202" text-anchor="middle">${
        showsBackward ? `${backward?.symbol || '∵'} ${backwardRole}` : 'no converse'
      }</text>
      <circle class="compact-bridge-dot" cx="180" cy="115" r="10" />
      <text class="compact-bridge-dot-label" x="180" y="120" text-anchor="middle">${compactBridgeSignal(relation.signal)}</text>
    </svg>
  `;
}

function compactBridgeSignal(signal = '↔') {
  if (signal.includes('↔')) return '↔';
  if (signal.includes('->') || signal.includes('→')) return '→';
  if (signal.length <= 2) return signal;
  return '•';
}

function compactShortLabel(label) {
  const compact = label
    .replace(' compactness', '')
    .replace(' theorem', '')
    .replace(' in R^n', '')
    .split(' ')
    .slice(0, 2)
    .join(' ');
  return compact.length > 18 ? `${compact.slice(0, 16)}...` : compact;
}

function getCurrentMstWorld() {
  return mstWorldMeta[state.mstWorld] || mstWorlds[0];
}

function getMstPairs(worldOrNodes) {
  const nodes = Array.isArray(worldOrNodes) ? worldOrNodes : worldOrNodes.nodes;
  const explicitEdges = Array.isArray(worldOrNodes) ? null : worldOrNodes.edges;

  if (explicitEdges) {
    return explicitEdges
      .map(([firstId, secondId]) => {
        const first = nodes.find((node) => node.id === firstId);
        const second = nodes.find((node) => node.id === secondId);
        return first && second ? [first, second] : null;
      })
      .filter(Boolean);
  }

  const pairs = [];
  for (let i = 0; i < nodes.length; i += 1) {
    for (let j = i + 1; j < nodes.length; j += 1) {
      pairs.push([nodes[i], nodes[j]]);
    }
  }
  return pairs;
}

function getMstEdgeId(a, b) {
  return [a.id, b.id].sort().join('__');
}

function parseMstEdge(edgeId, nodes) {
  if (!edgeId) return null;
  const [firstId, secondId] = edgeId.split('__');
  const ordered = nodes.filter((node) => node.id === firstId || node.id === secondId);
  return ordered.length === 2 ? ordered : null;
}

function renderMstSection() {
  if (!elements.mstWorldFilters) return;

  const world = getCurrentMstWorld();
  const nodes = world.nodes;
  const selectedNode = nodes.find((node) => node.id === state.selectedMstNodeId) || nodes[0];
  const pairs = getMstPairs(world);
  const selectedPair = parseMstEdge(state.selectedMstEdge, nodes);

  state.selectedMstNodeId = selectedNode.id;
  if (state.selectedMstEdge && !selectedPair) {
    state.selectedMstEdge = null;
  }

  elements.mstWorldFilters.innerHTML = mstWorlds
    .map(
      (item) => `
        <button
          class="filter-chip ${item.id === world.id ? 'is-active' : ''}"
          data-mst-world="${item.id}"
          aria-pressed="${item.id === world.id}"
        >
          ${item.label}
        </button>
      `
    )
    .join('');

  elements.mstWorldNote.innerHTML = `
    <p>${world.note}</p>
    <span>${world.caveat}</span>
    ${renderMstWorldLegend(world)}
    ${renderMstRelationLegend(world)}
  `;

  elements.mstGraph.innerHTML = renderMstGraph(world, selectedNode, selectedPair);
  elements.mstBridgeList.innerHTML = pairs
    .map(([a, b]) => {
      const edgeId = getMstEdgeId(a, b);
      const relation = getMstRelation(world, a, b);
      const aFamily = mstFamilyMeta[a.family] || mstFamilyMeta.variant;
      const bFamily = mstFamilyMeta[b.family] || mstFamilyMeta.variant;
      return `
        <button class="mst-edge-chip ${relation.kind} ${state.selectedMstEdge === edgeId ? 'is-active' : ''}" data-mst-edge="${edgeId}">
          <span><i class="mst-mini-symbol ${aFamily.className}">${a.symbol || ''}</i>${a.title}</span>
          <strong>${mstEdgeSignalLabel(relation)} ${relation.type}</strong>
          <span><i class="mst-mini-symbol ${bFamily.className}">${b.symbol || ''}</i>${b.title}</span>
        </button>
      `;
    })
    .join('');

  elements.mstDetail.innerHTML = selectedPair
    ? renderMstRelationDetail(world, selectedPair[0], selectedPair[1])
    : renderMstNodeDetail(world, selectedNode);
  scheduleBridgeListBalance();
}

function renderMstWorldLegend(world) {
  const families = [...new Set(world.nodes.map((node) => node.family))];
  return `
    <div class="mst-legend" aria-label="MST symbol legend">
      ${families
        .map((familyId) => {
          const family = mstFamilyMeta[familyId] || mstFamilyMeta.variant;
          return `
            <span class="mst-legend-item ${family.className}">
              <i aria-hidden="true"></i>
              <strong>${family.label}</strong>
              <em>${mstFamilyNote(familyId)}</em>
            </span>
          `;
        })
        .join('')}
    </div>
  `;
}

function mstFamilyNote(familyId) {
  const notes = {
    definition: 'the optimization target',
    cut: 'safe edges through cuts/slices',
    cycle: 'reject or exchange cycle edges',
    exchange: 'single-swap proof engine',
    algorithm: 'Prim, Kruskal, or greedy invariant',
    matroid: 'abstract greedy structure',
    path: 'all-pairs bottleneck paths',
    threshold: 'connectivity at every scale',
    lexicographic: 'sorted edge-vector optimality',
    variant: 'related but not equivalent',
    stronger: 'implies MST-style behavior',
    warning: 'common false friend',
    consequence: 'theorem powered by MST logic',
  };
  return notes[familyId] || 'proof face';
}

function renderMstRelationLegend(world) {
  const worldNote =
    world.id === 'certificates'
      ? '<span><i class="mst-relation-key clique"></i>complete graph = equivalent MST certificates, so the clique is a proof-comparison tool</span>'
      : world.id === 'algorithm-proofs'
        ? '<span><i class="mst-relation-key route"></i>complete graph = proof routes, not all logical equivalences</span>'
        : '<span><i class="mst-relation-key explicit"></i>shown edges only = implication, strengthening, consequence, or warning</span>';

  return `
    <div class="mst-relation-legend" aria-label="MST edge legend">
      <span><i class="mst-relation-key equivalent"></i>↔ means equivalent in the named scope</span>
      <span><i class="mst-relation-key implies"></i>→ means one-way consequence; reverse may fail</span>
      <span><i class="mst-relation-key warning"></i>≠ means nearby idea, no implication claimed</span>
      ${worldNote}
    </div>
  `;
}

function renderMstGraph(world, selectedNode, selectedPair) {
  const nodes = world.nodes;
  const center = { x: 50, y: 50 };
  const radius = nodes.length > 6 ? 37 : 35;
  const positions = nodes.map((node, index) => {
    const angle = -Math.PI / 2 + (Math.PI * 2 * index) / nodes.length;
    return {
      ...node,
      x: center.x + Math.cos(angle) * radius,
      y: center.y + Math.sin(angle) * radius,
    };
  });
  const positionById = Object.fromEntries(positions.map((node) => [node.id, node]));
  const pairs = getMstPairs(world);
  const selectedEdgeId = selectedPair ? getMstEdgeId(selectedPair[0], selectedPair[1]) : null;

  return `
    <div class="mst-orbit">
      <svg class="mst-complete-svg" viewBox="0 0 100 100" role="img" aria-label="MST proof graph">
        ${pairs
          .map(([a, b]) => {
            const start = positionById[a.id];
            const end = positionById[b.id];
            const edgeId = getMstEdgeId(a, b);
            const relation = getMstRelation(world, a, b);
            const isActive =
              edgeId === selectedEdgeId ||
              (!selectedEdgeId && (a.id === selectedNode.id || b.id === selectedNode.id));
            return `
              ${renderMstEdgeHitbox(start, end, edgeId)}
              ${renderMstEdgeLine(start, end, relation, edgeId, isActive)}
              ${isActive ? renderMstEdgeSignalMarker(start, end, relation, edgeId) : ''}
            `;
          })
          .join('')}
      </svg>
      ${positions
        .map((node, index) => {
          const family = mstFamilyMeta[node.family] || mstFamilyMeta.variant;
          return `
            <button
              class="mst-node ${family.className} ${node.id === selectedNode.id && !selectedEdgeId ? 'is-active' : ''}"
              data-mst-node="${node.id}"
              style="left: ${node.x}%; top: ${node.y}%;"
              aria-label="${node.title}: ${family.label}"
            >
              <span class="mst-symbol">${node.symbol || index + 1}</span>
              <strong>${node.title}</strong>
              <small>${family.label}</small>
            </button>
          `;
        })
        .join('')}
    </div>
  `;
}

function renderMstEdgeHitbox(start, end, edgeId) {
  return `
    <path
      class="mst-edge-hitbox"
      d="M ${start.x.toFixed(2)} ${start.y.toFixed(2)} L ${end.x.toFixed(2)} ${end.y.toFixed(2)}"
      data-mst-edge="${edgeId}"
    />
  `;
}

function renderMstEdgeLine(start, end, relation, edgeId, isActive) {
  return `
    <path
      class="mst-edge ${relation.kind} ${isActive ? 'is-active' : ''}"
      d="M ${start.x.toFixed(2)} ${start.y.toFixed(2)} L ${end.x.toFixed(2)} ${end.y.toFixed(2)}"
      data-mst-edge="${edgeId}"
    />
  `;
}

function renderMstEdgeSignalMarker(start, end, relation, edgeId) {
  const x = ((start.x + end.x) / 2).toFixed(2);
  const y = ((start.y + end.y) / 2).toFixed(2);
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const angle = (Math.atan2(dy, dx) * 180) / Math.PI;
  return `
    <g class="mst-edge-signal ${relation.kind}" data-mst-edge="${edgeId}" transform="translate(${x} ${y}) rotate(${angle.toFixed(2)})">
      <circle cx="0" cy="0" r="3.35" />
      <text x="0" y="0.85" text-anchor="middle" transform="rotate(${-angle.toFixed(2)})">${mstGraphSignal(relation)}</text>
    </g>
  `;
}

function renderMstNodeDetail(world, node) {
  const family = mstFamilyMeta[node.family] || mstFamilyMeta.variant;
  return `
    <p class="eyebrow">${world.label}</p>
    <div class="badge-row">
      ${renderBadge(world.short, 'mst-world')}
      ${renderBadge(family.label, family.className)}
    </div>
    <h2 class="detail-title mst-title-with-symbol"><span class="${family.className}">${node.symbol || ''}</span>${node.title}</h2>
    <p class="detail-summary">${node.short}</p>
    <div class="mst-demo-card">
      ${renderMstDemo(node.demo, node.title)}
    </div>
    <div class="detail-block mst-definition-block">
      <h3>Formal read</h3>
      <p>${node.definition}</p>
    </div>
    ${renderMstTermList(getMstNodeTerms(node))}
    <div class="detail-block">
      <h3>Intuition</h3>
      <p>${node.intuition}</p>
    </div>
    <div class="detail-block">
      <h3>Proof role</h3>
      <p>${node.proof}</p>
    </div>
    <div class="detail-block mst-clique-note">
      <h3>${world.complete ? 'Clique proof' : 'Comparison edge'}</h3>
      <p>${
        world.id === 'certificates'
          ? 'In this world, every node is an MST certificate. Clicking any edge shows a route between two equivalent ways of recognizing the same object.'
          : world.id === 'algorithm-proofs'
            ? 'The clique here compares proof machines. It is deliberately not saying every proof method is a definition.'
            : 'This world only draws edges where a real implication, strengthening, consequence, or warning is worth studying.'
      }</p>
    </div>
  `;
}

function renderMstRelationDetail(world, a, b) {
  const relation = getMstRelation(world, a, b);
  const aFamily = mstFamilyMeta[a.family] || mstFamilyMeta.variant;
  const bFamily = mstFamilyMeta[b.family] || mstFamilyMeta.variant;
  return `
    <p class="eyebrow">${world.label} bridge</p>
    <div class="badge-row">
      ${renderBadge(relation.type, relation.kind)}
      ${renderBadge(aFamily.label, aFamily.className)}
      ${renderBadge(bFamily.label, bFamily.className)}
    </div>
    <h2 class="detail-title mst-relation-title">
      <span class="${aFamily.className} proof-left">${a.symbol || ''}</span>
      ${a.title}
      <em>${relation.signal || '↔'}</em>
      <span class="${bFamily.className} proof-right">${b.symbol || ''}</span>
      ${b.title}
    </h2>
    <p class="detail-summary">${relation.summary}</p>
    <div class="mst-demo-card">
      ${renderMstBridgeDemo(relation, a, b)}
    </div>
    ${renderMstRouteStrip(relation)}
    ${renderMstTermList(getMstRelationTerms(a, b, relation))}
    ${renderMstDirectionalProofs(relation, a, b)}
    <div class="detail-grid">
      <div class="fact">
        <span class="fact-label">Left statement</span>
        <span class="fact-value">${a.short}</span>
      </div>
      <div class="fact">
        <span class="fact-label">Right statement</span>
        <span class="fact-value">${b.short}</span>
      </div>
    </div>
    <div class="detail-block">
      <h3>What changes in your head</h3>
      <p>${relation.takeaway}</p>
    </div>
    <div class="detail-block">
      <h3>Scope note</h3>
      <p>${relation.caveat}</p>
    </div>
  `;
}

function renderMstRouteStrip(relation) {
  const mode = getMstArrowMode(relation);
  const labels = {
    both: relation.kind === 'mst-proof-route' ? 'proof comparison' : 'equivalence route',
    forward: 'one-way route',
    backward: 'reverse implication',
    none: 'near-miss warning',
  };
  return `
    <div class="mst-route-strip">
      <span>${labels[mode] || 'proof route'}</span>
      <p>${relation.route}</p>
    </div>
  `;
}

function renderMstDirectionalProofs(relation, a, b) {
  const directions = getMstDirectionalProofs(relation, a, b);
  if (!directions.length) return '';
  return `
    <div class="mst-proof-directions" aria-label="MST directional proof routes">
      ${directions
        .map((direction) => {
          const fromTitle = direction.from === 'right' ? b.title : a.title;
          const toTitle = direction.to === 'left' ? a.title : b.title;
          return `
            <section class="mst-proof-direction proof-${direction.role || 'lemma'}">
              <div class="mst-proof-direction-head">
                <span class="mst-proof-main-symbol">${direction.symbol || '∴'}</span>
                <div>
                  <strong>${direction.title}</strong>
                  <small>
                    <span class="proof-side proof-${direction.from}">${direction.from}</span>
                    <b>${direction.arrow || '⇒'}</b>
                    <span class="proof-side proof-${direction.to}">${direction.to}</span>
                    ${fromTitle} to ${toTitle}
                  </small>
                </div>
                <em>${mstProofRoleLabel(direction.role)}</em>
              </div>
              <p>${direction.summary}</p>
              <div class="mst-proof-lines">
                ${(direction.steps || [])
                  .map(
                    (step, index, list) => `
                      <div class="mst-proof-line">
                        <span>${mstProofLineSymbol(index, list.length)}</span>
                        <p>${step}</p>
                      </div>
                    `
                  )
                  .join('')}
              </div>
            </section>
          `;
        })
        .join('')}
    </div>
  `;
}

function getMstDirectionalProofs(relation, a, b) {
  if (relation.directions?.length) return relation.directions;

  const mode = getMstArrowMode(relation);
  const proofSteps = relation.steps?.length
    ? relation.steps
    : [
        `Start with ${a.title}.`,
        `Use the route: ${relation.route}.`,
        `Conclude ${b.title}.`,
      ];

  if (mode === 'none') {
    return [
      {
        from: 'left',
        to: 'right',
        role: 'warning',
        symbol: '∵',
        arrow: '≠',
        title: 'No implication is being claimed',
        summary:
          'This edge exists because the two statements are easy to confuse, not because either statement proves the other.',
        steps: relation.steps || [
          `Compare the objective in ${a.title} with the objective in ${b.title}.`,
          'They optimize different quantities or omit the greedy invariant.',
          'Treat this as a warning edge, not a theorem edge.',
        ],
      },
    ];
  }

  const role =
    relation.kind === 'mst-equivalent'
      ? 'equivalence'
      : relation.kind === 'mst-proof-route'
        ? 'algorithm'
        : relation.kind === 'mst-warning-link'
          ? 'warning'
          : relation.kind === 'mst-stronger-link'
            ? 'corollary'
            : 'lemma';
  const directions = [];

  if (mode === 'forward' || mode === 'both') {
    directions.push({
      from: 'left',
      to: 'right',
      role,
      symbol: relation.kind === 'mst-implies' ? '∴' : '∵',
      title: `${a.title} gives ${b.title}`,
      summary:
        mode === 'both'
          ? 'This is one half of the equivalence or proof comparison; the route runs left to right.'
          : 'This is the asserted implication direction; the reverse direction is not part of this edge.',
      steps: proofSteps,
    });
  }

  if (mode === 'backward' || mode === 'both') {
    directions.push({
      from: 'right',
      to: 'left',
      role,
      symbol: '∴',
      title: `${b.title} gives ${a.title}`,
      summary:
        mode === 'both'
          ? 'This is the reverse half, usually routed through the same exchange or greedy invariant.'
          : 'The stronger or more specific statement implies the baseline statement.',
      steps:
        mode === 'both'
          ? [
              `Start with ${b.title}.`,
              `Reverse the displayed route where the hypotheses allow it: ${relation.route}.`,
              `Conclude ${a.title}.`,
            ]
          : proofSteps,
    });
  }

  return directions;
}

function mstProofLineSymbol(index, length) {
  if (index === 0) return '∵';
  if (index === length - 1) return '∴';
  return '⇒';
}

function mstProofRoleLabel(role = 'lemma') {
  const labels = {
    equivalence: 'equivalence',
    lemma: 'lemma',
    corollary: 'corollary',
    algorithm: 'algorithm proof',
    exchange: 'exchange',
    clique: 'clique route',
    warning: 'scope check',
  };
  return labels[role] || role;
}

function renderMstTermList(terms = []) {
  if (!terms.length) return '';
  return `
    <div class="mst-term-list" aria-label="MST concept definitions">
      ${terms
        .map(
          (item) => `
            <div class="mst-term">
              <strong>${item.term}</strong>
              <p>${item.definition}</p>
            </div>
          `
        )
        .join('')}
    </div>
  `;
}

function getMstRelationTerms(a, b, relation) {
  const terms = [...getMstNodeTerms(a), ...getMstNodeTerms(b)];
  if (relation.kind === 'mst-proof-route') {
    terms.push({
      term: 'Proof route',
      definition:
        'A comparison between methods of proving greedy correctness. It is not automatically a logical equivalence between statements.',
    });
  }
  if (relation.kind === 'mst-warning-link') {
    terms.push({
      term: 'False friend',
      definition:
        'A statement that resembles MST language but optimizes a different objective or drops a necessary invariant.',
    });
  }

  const seen = new Set();
  return terms.filter((term) => {
    if (seen.has(term.term)) return false;
    seen.add(term.term);
    return true;
  });
}

function getMstNodeTerms(node) {
  const familyTerms = {
    cut: [
      {
        term: 'Cut / slice',
        definition:
          'A partition of the vertices into two nonempty sides. An edge crosses the cut when its endpoints lie on opposite sides.',
      },
      {
        term: 'Safe edge',
        definition:
          'An edge that can be added to the current forest while preserving the promise that some MST still extends it.',
      },
    ],
    cycle: [
      {
        term: 'Cycle / circle property',
        definition:
          'On any cycle, a strictly heaviest edge is excluded from every MST; with ties, at least one heaviest edge can be safely omitted.',
      },
    ],
    exchange: [
      {
        term: 'Exchange',
        definition:
          'Add one non-tree edge to create a cycle, then delete one edge from that cycle to obtain another spanning tree.',
      },
    ],
    matroid: [
      {
        term: 'Graphic matroid',
        definition:
          'The matroid whose independent sets are forests of a graph and whose bases are spanning trees in a connected graph.',
      },
    ],
    path: [
      {
        term: 'Bottleneck path cost',
        definition:
          'The cost of a path measured by its largest edge weight, rather than by the sum of its edge weights.',
      },
    ],
    threshold: [
      {
        term: 'Threshold graph G_{<=τ}',
        definition:
          'The subgraph containing all vertices and only the edges whose weights are at most the threshold τ.',
      },
    ],
    lexicographic: [
      {
        term: 'Lexicographic order',
        definition:
          'Compare sorted edge-weight lists from left to right; the first position where they differ decides which list is smaller.',
      },
    ],
  };
  const nodeTerms = {
    'minimum-tree': [
      {
        term: 'Spanning tree',
        definition:
          'A connected, acyclic subgraph containing every vertex. On n vertices it has exactly n - 1 edges.',
      },
    ],
    'mst-baseline': [
      {
        term: 'Spanning tree',
        definition:
          'A connected, acyclic subgraph containing every vertex. On n vertices it has exactly n - 1 edges.',
      },
    ],
    'min-total-property': [
      {
        term: 'Minimum total weight',
        definition:
          'The usual MST objective: compare spanning trees by the sum of all selected edge weights.',
      },
    ],
    'single-swap-property': [
      {
        term: 'Spanning-tree exchange graph',
        definition:
          'The graph whose vertices are spanning trees and whose edges connect trees differing by one add-delete edge exchange.',
      },
    ],
    'fundamental-cut-property': [
      {
        term: 'Fundamental cut',
        definition:
          'The cut produced by deleting a chosen tree edge from T. The deleted edge crosses that cut.',
      },
    ],
    'fundamental-cycle-property': [
      {
        term: 'Fundamental cycle',
        definition:
          'The unique cycle produced by adding one non-tree edge to T.',
      },
    ],
    'all-pairs-minimax-property': [
      {
        term: 'Bottleneck distance',
        definition:
          'The minimum possible largest-edge weight over all paths connecting a pair of vertices.',
      },
    ],
    'threshold-property': [
      {
        term: 'Connectivity at scale',
        definition:
          'Two vertices are connected at threshold τ when there is a path between them using only edges of weight at most τ.',
      },
    ],
    'lex-bottleneck-property': [
      {
        term: 'Descending edge vector',
        definition:
          'The list of a tree’s edge weights sorted from largest to smallest, used to compare worst edge, then second-worst edge, and so on.',
      },
    ],
    'kruskal-prefix-property': [
      {
        term: 'Graphic rank',
        definition:
          'For a subgraph, the size of a maximal forest in it. In a component with m vertices, the rank contribution is m - 1.',
      },
    ],
    'single-linkage-property': [
      {
        term: 'Dendrogram',
        definition:
          'A hierarchy of clusters recording the threshold values where connected components merge.',
      },
    ],
    'kruskal-certificate': [
      {
        term: 'Kruskal order',
        definition:
          'Process edges from lightest to heaviest, accepting an edge exactly when it joins two different forest components.',
      },
    ],
    'kruskal-cut-proof': [
      {
        term: 'Forest invariant',
        definition:
          'The accepted edges remain acyclic and are always extendable to some MST.',
      },
    ],
    'kruskal-cycle-proof': [
      {
        term: 'Reject rule',
        definition:
          'If an edge closes a cycle with already accepted no-heavier edges, it is safe to reject for MST construction.',
      },
    ],
    'prim-certificate': [
      {
        term: 'Frontier cut',
        definition:
          'The cut between the vertices already reached by Prim and the vertices not reached yet.',
      },
    ],
    'prim-invariant': [
      {
        term: 'Frontier cut',
        definition:
          'The cut between the vertices already reached by Prim and the vertices not reached yet.',
      },
    ],
    mbst: [
      {
        term: 'Bottleneck',
        definition:
          'The largest edge weight used by a tree or path. MBST minimizes this maximum, not the sum.',
      },
    ],
    'minimax-path': [
      {
        term: 'Minimax path',
        definition:
          'A path that minimizes its largest edge weight among all paths connecting the same endpoints.',
      },
    ],
    'unique-mst': [
      {
        term: 'Distinct weights',
        definition:
          'If all edge weights are distinct, every cut and cycle has a unique lightest/heaviest witness, which forces a unique MST.',
      },
    ],
    'shortest-path-tree': [
      {
        term: 'Shortest-path tree',
        definition:
          'A rooted tree preserving shortest distances from the root to every vertex. Its objective is path length, not total tree weight.',
      },
    ],
    clustering: [
      {
        term: 'Spacing',
        definition:
          'For a clustering, the smallest edge weight connecting two different clusters. Kruskal maximizes this when stopped at k components.',
      },
    ],
  };

  const terms = [...(familyTerms[node.family] || []), ...(nodeTerms[node.id] || [])];
  const seen = new Set();
  return terms.filter((term) => {
    if (seen.has(term.term)) return false;
    seen.add(term.term);
    return true;
  });
}

function mstRelation(type, kind, summary, route, takeaway, caveat, steps = [], signal = '↔', directions = [], arrow = null) {
  return { type, kind, summary, route, takeaway, caveat, steps, signal, directions, arrow };
}

function getMstRelation(world, a, b) {
  const ids = new Set([a.id, b.id]);
  const has = (id) => ids.has(id);

  if (world.id === 'certificates') {
    if (has('cut-certificate') && has('cycle-certificate')) {
      return mstRelation(
        'Cut-cycle duality',
        'mst-equivalent',
        'Tree-edge cut optimality and non-tree-edge cycle optimality are two sides of the same exchange test.',
        'delete a tree edge -> cut witness; add a non-tree edge -> fundamental cycle witness',
        'A cut tells you why a chosen tree edge cannot be improved; a cycle tells you why a skipped edge cannot improve the tree.',
        'This is an equivalence for spanning trees of a connected weighted graph, with ties handled by non-strict inequalities.',
        [],
        '↔',
        [
          {
            from: 'left',
            to: 'right',
            role: 'equivalence',
            symbol: '∵',
            title: 'Cut optimality gives cycle optimality',
            summary:
              'A non-tree edge creates a cycle. Removing any tree edge on that cycle creates a cut crossed by the non-tree edge.',
            steps: [
              'Take a non-tree edge f and add it to T; this creates the fundamental cycle.',
              'For any tree edge e on that cycle, deleting e partitions T into two sides, and f crosses that cut.',
              'Cut optimality gives w(e) <= w(f), so f cannot be an improving replacement.',
            ],
          },
          {
            from: 'right',
            to: 'left',
            role: 'equivalence',
            symbol: '∴',
            title: 'Cycle optimality gives cut optimality',
            summary:
              'A crossing edge for the cut made by deleting a tree edge creates a fundamental cycle containing that tree edge.',
            steps: [
              'Delete a tree edge e from T, forming two components and a cut.',
              'Let f be any other edge crossing that cut. Adding f reconnects the components and creates a cycle containing e.',
              'Cycle optimality gives w(e) <= w(f), so e is lightest across its cut.',
            ],
          },
        ]
      );
    }

    if (has('minimum-tree') && has('cut-certificate')) {
      return mstRelation(
        'Fundamental cut certificate',
        'mst-equivalent',
        'A spanning tree is minimum exactly when every one of its edges is justified by the cut it alone bridges.',
        'MST -> no cheaper crossing replacement -> every fundamental cut is optimal',
        'The global minimum can be checked through n - 1 local replacement tests.',
        'Assumes T is already a spanning tree. The certificate uses weak inequalities when weights tie.',
        [],
        '↔',
        [
          {
            from: 'left',
            to: 'right',
            role: 'equivalence',
            symbol: '∵',
            title: 'Minimum tree forces cut optimality',
            summary:
              'A lighter edge across a fundamental cut would replace a tree edge and lower the total weight.',
            steps: [
              'Choose e in T and delete it; T splits into two components.',
              'If some crossing edge f had w(f) < w(e), then T - e + f would still be a spanning tree.',
              'That tree would be cheaper than T, contradicting minimality.',
            ],
          },
          {
            from: 'right',
            to: 'left',
            role: 'equivalence',
            symbol: '∴',
            title: 'Cut optimality forces minimality',
            summary:
              'Exchange edges from any competing tree into T without increasing total weight.',
            steps: [
              'Compare T with any other spanning tree S.',
              'Pick e in T \\ S; S must contain an edge f crossing the cut made by deleting e from T.',
              'Cut optimality gives w(e) <= w(f), so exchanging f for e in S does not increase weight; repeat until S becomes T.',
            ],
          },
        ]
      );
    }

    if (has('minimum-tree') && has('cycle-certificate')) {
      return mstRelation(
        'Fundamental cycle certificate',
        'mst-equivalent',
        'A spanning tree is minimum exactly when every skipped edge loses to the path already in the tree.',
        'MST -> no cheaper cycle swap -> non-tree edges are blocked',
        'Instead of defending chosen edges, this defends every rejected edge.',
        'Assumes T is a spanning tree. With tied weights, “blocked” means no strictly cheaper exchange.',
        [
          'Add a non-tree edge f to T and inspect the unique cycle.',
          'If some tree edge e on that cycle had w(e) > w(f), then T - e + f would be cheaper.',
          'Conversely, if no such improving cycle swap exists, repeated exchanges cannot produce a cheaper spanning tree.',
        ]
      );
    }

    if (has('exchange-certificate')) {
      return mstRelation(
        'Exchange certificate',
        'mst-equivalent',
        'The exchange graph of spanning trees turns local no-improvement into global optimality.',
        `${a.title} -> one-edge exchange tests -> ${b.title}`,
        'MST proofs often become clearer once every argument is seen as “add one edge, delete one edge.”',
        'This uses the fact that all spanning trees of a connected graph are connected by single-edge exchanges.',
        [
          'A non-tree edge creates exactly one cycle when added to a spanning tree.',
          'Deleting an edge on that cycle gives another spanning tree.',
          'If no such swap lowers weight, moving through the spanning-tree exchange graph cannot find a cheaper tree.',
        ]
      );
    }

    if (has('kruskal-certificate') || has('prim-certificate')) {
      return mstRelation(
        'Greedy output certificate',
        'mst-equivalent',
        'A tree is MST iff a suitable greedy tie-breaking can reveal it.',
        'cut/exchange certificate -> safe greedy choices -> algorithm outputs T',
        'Prim and Kruskal are not magic recipes; they are disciplined ways of repeatedly taking safe edges.',
        'The “some tie-breaking” clause matters when equal weights allow multiple MSTs.',
        [
          'If an algorithm outputs T, the greedy correctness theorem says T is an MST.',
          'If T is an MST, tie-breaking can prefer T-edges whenever the algorithm has a safe choice among equal-weight edges.',
          'Cut and exchange optimality guarantee those preferred choices remain safe.',
        ]
      );
    }

    return mstRelation(
      'MST certificate clique',
      'mst-equivalent',
      'Both statements are certificates for the same minimum spanning tree property.',
      `${a.title} -> exchange hub -> ${b.title}`,
      'The clique is useful because you can route a proof through whichever certificate makes the local picture most vivid.',
      'All equivalences here assume a connected weighted graph and that T is a spanning tree.',
      [
        `Translate ${a.title} into the no-improving-exchange condition.`,
        'Use the exchange graph of spanning trees as the common proof hub.',
        `Translate the exchange condition into ${b.title}.`,
      ]
    );
  }

  if (world.id === 'properties') {
    if (has('min-total-property') && has('single-swap-property')) {
      return mstRelation(
        'Exchange characterization',
        'mst-equivalent',
        'Minimum total weight is equivalent to having no improving one-edge exchange.',
        'minimum total weight ⇄ local optimality in the spanning-tree exchange graph',
        'The reason one-swap checks are enough is structural: spanning trees are connected to one another by these swaps.',
        'T must be a spanning tree. “No improving” means no strictly lower total weight after a valid swap.',
        [],
        '↔',
        [
          {
            from: 'left',
            to: 'right',
            role: 'equivalence',
            symbol: '∵',
            title: 'A minimum tree has no improving swap',
            summary:
              'Any improving swap would produce another spanning tree with smaller total weight.',
            steps: [
              'Assume T has minimum total weight.',
              'Add a non-tree edge f and delete a tree edge e on the created cycle so the result is still a spanning tree.',
              'If w(f) < w(e), then T - e + f is cheaper than T, contradiction.',
            ],
          },
          {
            from: 'right',
            to: 'left',
            role: 'equivalence',
            symbol: '∴',
            title: 'No improving swap forces global minimality',
            summary:
              'Move from T toward any cheaper spanning tree by single exchanges; one step would have to improve.',
            steps: [
              'Assume no one-edge exchange improves T.',
              'If some spanning tree S were cheaper, choose an exchange path from T to S in the spanning-tree graph.',
              'Among e in T\\S, the cut property yields a swap T-e+f with w(f) <= w(e); since w(S) < w(T), at least one such swap is strictly improving, contradiction.',
            ],
          },
        ]
      );
    }

    if (has('min-total-property') && has('fundamental-cut-property')) {
      return mstRelation(
        'Fundamental cut characterization',
        'mst-equivalent',
        'A spanning tree is MST exactly when each tree edge is lightest across its fundamental cut.',
        'delete tree edge -> exposed cut -> compare crossing replacements',
        'Cut optimality lets every chosen edge justify its place locally.',
        'Use weak inequalities when ties occur; unique lightest witnesses give forced edges.',
        [],
        '↔',
        [
          {
            from: 'left',
            to: 'right',
            role: 'equivalence',
            symbol: '∵',
            title: 'Minimum total gives cut optimality',
            summary:
              'A lighter crossing replacement would reconnect the two components at lower cost.',
            steps: [
              'Delete e from T, producing a cut.',
              'If f crossed that cut with w(f) < w(e), then T - e + f would be a spanning tree.',
              'Its total weight would be smaller, contradicting minimum total weight.',
            ],
          },
          {
            from: 'right',
            to: 'left',
            role: 'equivalence',
            symbol: '∴',
            title: 'Cut optimality gives minimum total',
            summary:
              'Compare T to any spanning tree S and exchange T-edges into S without increasing weight.',
            steps: [
              'Pick e in T \\ S and delete e from T; S contains some edge f crossing the resulting cut.',
              'Fundamental cut optimality gives w(e) <= w(f).',
              'Replace f by e in S without increasing total weight; repeat until S becomes T.',
            ],
          },
        ]
      );
    }

    if (has('min-total-property') && has('fundamental-cycle-property')) {
      return mstRelation(
        'Fundamental cycle characterization',
        'mst-equivalent',
        'A spanning tree is MST exactly when every non-tree edge is blocked by its path in T.',
        'add non-tree edge -> fundamental cycle -> no heavier path edge to remove',
        'Cycle optimality defends the rejected edges instead of the chosen edges.',
        'With ties, the condition is max edge on the T-path <= weight of the non-tree edge.',
        [
          'If T is minimum, then a non-tree edge f cannot be lighter than a removable path edge e.',
          'Otherwise T - e + f would be a cheaper spanning tree.',
          'Conversely, if every non-tree edge is no lighter than all path edges it could replace, then no improving exchange exists.',
        ]
      );
    }

    if (has('min-total-property') && has('all-pairs-minimax-property')) {
      return mstRelation(
        'Minimax path characterization',
        'mst-equivalent',
        'A spanning tree is MST exactly when every path inside it is a bottleneck-optimal path in the graph.',
        'cycle property ⇄ every T-path minimizes its maximum edge',
        'MSTs preserve all bottleneck distances even though they do not preserve ordinary shortest-path distances.',
        'This property assumes path cost means maximum edge weight, not sum of edge weights.',
        [],
        '↔',
        [
          {
            from: 'left',
            to: 'right',
            role: 'equivalence',
            symbol: '∵',
            title: 'MST gives all-pairs minimax paths',
            summary:
              'A better bottleneck path would create a cycle exchange that removes a heavier tree edge.',
            steps: [
              'Take vertices u and v and let e be the heaviest edge on their T-path.',
              'If another u-v path had all edges lighter than e, adding that path to T creates a cycle containing e.',
              'Cycle exchange would remove e and lower the tree, contradicting MST optimality.',
            ],
          },
          {
            from: 'right',
            to: 'left',
            role: 'equivalence',
            symbol: '∴',
            title: 'Minimax paths give cycle optimality',
            summary:
              'Use any non-tree edge as a one-edge alternate path between its endpoints.',
            steps: [
              'Let f = uv be a non-tree edge of weight w(f).',
              'The one-edge path f has bottleneck w(f), so the T-path from u to v has bottleneck at most w(f).',
              'Thus every edge on that T-path has weight <= w(f), which is the fundamental cycle condition.',
            ],
          },
        ]
      );
    }

    if (has('min-total-property') && has('threshold-property')) {
      return mstRelation(
        'Threshold connectivity characterization',
        'mst-equivalent',
        'A spanning tree is MST exactly when it preserves connectivity at every weight threshold.',
        'MST ⇄ minimax paths ⇄ components of T_{<=τ} equal components of G_{<=τ}',
        'This is the cleanest “sparse certificate” view: the MST remembers when every pair first becomes connected.',
        'Thresholds can be checked only at edge weights, since components change only there.',
        [
          'MST gives all-pairs minimax paths.',
          'A minimax path with bottleneck <= τ exists exactly when the endpoints are connected in G_{<=τ}.',
          'Therefore T_{<=τ} and G_{<=τ} have the same connected components for every τ; conversely, use τ = w(f) for each non-tree edge f to recover cycle optimality.',
        ]
      );
    }

    if (has('min-total-property') && has('lex-bottleneck-property')) {
      return mstRelation(
        'Lexicographic MST characterization',
        'mst-equivalent',
        'MSTs are exactly the spanning trees with lexicographically minimum sorted edge-weight vectors.',
        'Kruskal thresholds -> smallest possible largest edge, then second-largest, then third-largest',
        'Lexicographic bottleneck optimality is the sharpened form of the bottleneck theorem.',
        'Sort edge weights from largest to smallest before comparing; all MSTs share the same sorted weight multiset.',
        [],
        '↔',
        [
          {
            from: 'left',
            to: 'right',
            role: 'equivalence',
            symbol: '∵',
            title: 'MST gives lexicographic optimality',
            summary:
              'Kruskal maximizes the rank achieved below each threshold, fixing the best possible sorted weight profile.',
            steps: [
              'Run Kruskal from light to heavy.',
              'At every threshold τ, the accepted edges form a maximal forest of G_{<=τ}.',
              'That means no spanning tree can have more edges below any threshold, which is exactly lexicographic optimality of the descending weight vector.',
            ],
          },
          {
            from: 'right',
            to: 'left',
            role: 'equivalence',
            symbol: '∴',
            title: 'Lexicographic optimality gives MST',
            summary:
              'If a tree failed the cycle property, one exchange would improve its sorted vector.',
            steps: [
              'Suppose a non-tree edge f is lighter than some edge e on the T-path between its endpoints.',
              'The swap T - e + f replaces a heavier edge by a lighter edge and leaves all other weights unchanged.',
              'The sorted descending vector becomes lexicographically smaller, contradiction.',
            ],
          },
        ]
      );
    }

    if (has('min-total-property') && has('kruskal-prefix-property')) {
      return mstRelation(
        'Prefix rank characterization',
        'mst-equivalent',
        'A spanning tree is MST exactly when each threshold prefix has maximal forest rank.',
        'for every τ: T_{<=τ} spans each component of G_{<=τ}',
        'This is the rank-count version of threshold connectivity and the reason Kruskal is correct before it finishes.',
        'Equivalent to checking that T_{<=τ} has |V(C)| - 1 edges inside each component C of G_{<=τ}.',
        [
          'Threshold connectivity says T_{<=τ} and G_{<=τ} have the same connected components.',
          'Inside each component, T_{<=τ} is acyclic, so having the same components means it is a spanning forest there.',
          'That is exactly the maximal-rank prefix condition.',
        ]
      );
    }

    if (has('min-total-property') && has('bottleneck-property')) {
      return mstRelation(
        'Bottleneck consequence',
        'mst-implies',
        'Every MST is bottleneck-optimal, but bottleneck-optimal trees need not minimize total weight.',
        'minimum total weight -> minimum possible largest edge',
        'Bottleneck optimality is a useful first shadow of MST, but it forgets second-largest, third-largest, and total-weight information.',
        'Converse fails: multiple trees can have the same optimal largest edge while only one has minimum total weight.',
        [
          'Let e be the largest edge of an MST T.',
          'If another spanning tree avoided all edges of weight at least w(e), then G below that threshold would already be connected.',
          'Threshold connectivity would force T to connect using lower edges too, contradiction.',
        ],
        '→',
        [],
        'forward'
      );
    }

    if (has('fundamental-cut-property') && has('fundamental-cycle-property')) {
      return mstRelation(
        'Cut-cycle duality',
        'mst-equivalent',
        'Fundamental cut and fundamental cycle tests are the same exchange condition seen from opposite sides.',
        'delete tree edge for a cut; add non-tree edge for a cycle',
        'Cuts defend selected edges; cycles defend rejected edges.',
        'Both are fixed-tree characterizations, not merely algorithm rules.',
        [
          'A crossing edge for the cut made by deleting e creates a cycle containing e.',
          'A path edge on the cycle made by adding f defines a cut crossed by f.',
          'The same inequality w(tree edge) <= w(non-tree edge) appears in both languages.',
        ]
      );
    }

    if (has('single-swap-property') && has('fundamental-cycle-property')) {
      return mstRelation(
        'Swap-cycle equivalence',
        'mst-equivalent',
        'No improving swap is exactly the fundamental cycle condition written as an operation.',
        'add f -> unique cycle -> delete e -> compare w(f) with w(e)',
        'The cycle property is the inequality; the swap property is the move it prevents.',
        'For a valid spanning-tree swap, the deleted edge must lie on the fundamental cycle created by f.',
        [
          'Every valid single-edge swap adds one non-tree edge f.',
          'The removable tree edges are exactly the edges on the fundamental cycle C_T(f).',
          'No improving swap says w(f) >= w(e) for all such removable e, which is the cycle condition.',
        ]
      );
    }

    if (has('all-pairs-minimax-property') && has('threshold-property')) {
      return mstRelation(
        'Path-threshold equivalence',
        'mst-equivalent',
        'All-pairs minimax paths and threshold connectivity are the same statement with τ made explicit.',
        'bottleneck distance d∞(u,v) <= τ ⇄ u and v connected in G_{<=τ}',
        'The path view is local to a pair; the threshold view shows the whole clustering picture at once.',
        'The equivalence uses the bottleneck path cost max edge weight.',
        [
          'If the T-path from u to v has maximum edge <= τ, then u and v are connected in T_{<=τ}.',
          'If u and v are connected in G_{<=τ}, then some u-v path has bottleneck <= τ.',
          'The minimax property says the T-path also has bottleneck <= τ, so threshold components match.',
        ]
      );
    }

    if (has('threshold-property') && has('kruskal-prefix-property')) {
      return mstRelation(
        'Threshold-rank equivalence',
        'mst-equivalent',
        'Matching threshold components is equivalent to having a maximal forest at every threshold.',
        'same components ⇄ same graphic-matroid rank below every threshold',
        'This is the bridge from topology-looking connectivity to matroid-looking rank.',
        'For forests, component counts and edge ranks determine one another.',
        [
          'A forest on a component with m vertices is spanning exactly when it has m - 1 edges.',
          'Thus T_{<=τ} matches components of G_{<=τ} iff it has maximal possible rank in G_{<=τ}.',
          'Kruskal constructs precisely those maximal prefixes.',
        ]
      );
    }

    if (has('threshold-property') && has('single-linkage-property')) {
      return mstRelation(
        'Single-linkage consequence',
        'mst-consequence-link',
        'Threshold connectivity means the MST encodes the same merge tree as the full weighted graph.',
        'components of G_{<=τ} = components of T_{<=τ} -> same dendrogram',
        'This is why a sparse MST is enough for single-linkage clustering.',
        'This is a consequence of MST threshold behavior, not a separate total-weight characterization by itself.',
        [
          'Single-linkage clustering merges components as soon as an edge at threshold τ connects them.',
          'Threshold connectivity says the MST and the full graph have identical components at each τ.',
          'Therefore sweeping thresholds on the MST produces the same dendrogram.',
        ],
        '→',
        [],
        'forward'
      );
    }

    if (has('lex-bottleneck-property') && has('bottleneck-property')) {
      return mstRelation(
        'Lexicographic strengthens bottleneck',
        'mst-implies',
        'Lexicographic bottleneck optimality implies ordinary bottleneck optimality, but the converse loses information.',
        'minimize full sorted vector -> minimize first entry',
        'Ordinary bottleneck sees only the largest edge; lexicographic optimality keeps looking after ties in the largest edge.',
        'Converse fails whenever several trees share the best largest edge but differ on lower edges or total weight.',
        [
          'The first entry of the descending sorted vector is the largest edge weight.',
          'If T lexicographically minimizes the whole vector, it certainly minimizes that first entry.',
          'A tree that only minimizes the first entry may still have worse second or third entries.',
        ],
        '→',
        [],
        'forward'
      );
    }
  }

  if (world.id === 'algorithm-proofs') {
    if (has('safe-edge') && has('prim-invariant')) {
      return mstRelation(
        'Prim from safe edges',
        'mst-proof-route',
        'Prim is the safe-edge lemma applied over and over to the frontier cut of a connected growing set.',
        'frontier cut -> lightest crossing edge -> safe extension',
        'Prim feels local because the relevant cut is always the boundary of the already-grown component.',
        'This proves correctness of Prim, not a new definition of MST.',
        [
          'Maintain the invariant that the chosen edges are contained in some MST.',
          'At each step, take the cut between reached vertices and unreached vertices.',
          'The lightest edge crossing that cut is safe, so the invariant survives until a spanning tree is built.',
        ],
        '⇒',
        [],
        'forward'
      );
    }

    if (has('safe-edge') && has('kruskal-cut-proof')) {
      return mstRelation(
        'Kruskal from safe edges',
        'mst-proof-route',
        'Kruskal uses the safe-edge lemma on a cut separating two forest components.',
        'component cut -> globally next legal edge -> safe extension',
        'Kruskal is Prim without a single frontier: each component supplies a possible safe cut.',
        'This is a proof route for Kruskal correctness.',
        [
          'Keep accepted edges as a forest contained in some MST.',
          'When Kruskal accepts e, its endpoints are in different components.',
          'A cut separating one component from the other respects the forest, and e is lightest across it among legal crossing edges.',
        ],
        '⇒',
        [],
        'forward'
      );
    }

    if (has('kruskal-cut-proof') && has('kruskal-cycle-proof')) {
      return mstRelation(
        'Accept-reject dual proof',
        'mst-proof-route',
        'The cut proof explains accepted edges; the cycle proof explains rejected edges.',
        'safe to accept light cut edge ⇄ safe to reject late cycle edge',
        'Kruskal correctness can be read from either side of the same sorted process.',
        'These are proof perspectives, not different algorithm outputs.',
        [
          'Accepted edges connect different components and can be certified by a cut.',
          'Rejected edges close a cycle whose earlier edges are no heavier.',
          'Cut safety and cycle rejection together explain why the sorted scan loses nothing optimal.',
        ],
        '⇄'
      );
    }

    if (has('exchange-proof')) {
      return mstRelation(
        'Exchange proof route',
        'mst-proof-route',
        'The exchange argument is the common skeleton underneath Prim, Kruskal, and the safe-edge lemma.',
        `${a.title} -> compare greedy tree with an MST -> swap without increasing weight -> ${b.title}`,
        'Once you see the first missing greedy edge, most MST proofs become the same exchange move in different costumes.',
        'This is a proof-method bridge, so the arrows describe proof dependency rather than theorem equivalence.',
        [
          'Take an optimal tree that agrees with the greedy choices as long as possible.',
          'Add the first greedy edge missing from it; a cycle appears.',
          'Delete a suitable edge from that cycle, preserving optimality while increasing agreement with the greedy tree.',
        ],
        '⇄'
      );
    }

    if (has('matroid-greedy')) {
      return mstRelation(
        'Matroid abstraction',
        'mst-proof-route',
        'The graphic matroid packages the exchange argument into a general greedy theorem for bases.',
        'forest independence -> matroid exchange axiom -> greedy minimum-weight basis',
        'Kruskal is a theorem about forests, but also a shadow of a larger greedy principle.',
        'This abstraction proves Kruskal directly; Prim needs the graph cut picture to stay visible.',
        [
          'Forests are independent sets, and spanning trees are bases of the graphic matroid.',
          'The matroid exchange axiom is exactly what lets greedy choices be repaired inside an optimal basis.',
          'The minimum-weight basis theorem specializes to Kruskal producing an MST.',
        ],
        '⇄'
      );
    }

    return mstRelation(
      'Greedy proof comparison',
      'mst-proof-route',
      'These two proof machines can be routed through safe edges, cycle rejection, exchange, or the matroid theorem.',
      `${a.title} -> greedy invariant hub -> ${b.title}`,
      'The point of this clique is to compare proof styles, not to pretend every style is a separate definition.',
      'Read this as a proof-route edge; logical equivalence is not being asserted.',
      [
        `Start from the invariant used by ${a.title}.`,
        'Translate it into a safe-edge or exchange statement.',
        `Use that statement to understand ${b.title}.`,
      ],
      '⇄'
    );
  }

  if (world.id === 'variants') {
    if (has('mst-baseline') && has('mbst')) {
      return mstRelation(
        'MST implies MBST',
        'mst-implies',
        'Every MST minimizes the largest edge weight, but a minimum bottleneck tree need not minimize total weight.',
        'MST -> threshold cut/cycle argument -> minimum bottleneck spanning tree',
        'Bottleneck optimality is weaker than total-weight optimality.',
        'Converse fails: two trees can share the same largest edge while having different total weights.',
        [
          'Let T be an MST and let e be its largest edge.',
          'Kruskal has accepted all needed edges of weight at most w(e), so the graph below that threshold is connected enough to span.',
          'No spanning tree can avoid using an edge at least that heavy, so T is bottleneck-minimal.',
        ],
        '→',
        [],
        'forward'
      );
    }

    if (has('mst-baseline') && has('minimax-path')) {
      return mstRelation(
        'MST path bottleneck',
        'mst-consequence-link',
        'The path between two vertices in an MST is a minimax path for the original graph.',
        'MST cycle property -> no lower-bottleneck alternate path',
        'MSTs remember threshold connectivity even though they do not preserve shortest-path distances.',
        'This is a consequence of MST, not a full characterization by itself.',
        [
          'Take the path between u and v in an MST T, and let e be the heaviest edge on that path.',
          'If another u-v path had every edge lighter than e, adding that path to T would create a cycle containing e.',
          'Cycle exchange would remove e and lower the MST, contradiction.',
        ],
        '→',
        [],
        'forward'
      );
    }

    if (has('mst-baseline') && has('unique-mst')) {
      return mstRelation(
        'Uniqueness is stronger',
        'mst-stronger-link',
        'A unique MST is still an MST, but ordinary MST existence does not imply uniqueness.',
        'unique MST -> MST; distinct weights -> forced cut/cycle choices',
        'Uniqueness is a rigidity statement about the whole optimization landscape.',
        'Distinct weights are sufficient for uniqueness, not necessary.',
        [
          'If the graph has a unique MST, that tree is certainly a minimum spanning tree.',
          'The reverse fails whenever multiple equal-weight spanning trees achieve the same minimum total.',
          'Distinct weights force uniqueness because every cut and cycle has a unique decisive edge.',
        ],
        '←',
        [],
        'backward'
      );
    }

    if (has('mst-baseline') && has('shortest-path-tree')) {
      return mstRelation(
        'Different objective',
        'mst-warning-link',
        'Shortest-path trees optimize root distances; MSTs optimize total tree weight.',
        'Dijkstra objective ≠ MST objective',
        'The two trees can coincide, but neither theorem is a substitute for the other.',
        'No implication is claimed in either direction.',
        [
          'An MST may give a long root-to-vertex route because it cares about total weight.',
          'A shortest-path tree may include an expensive edge because it helps one vertex distance.',
          'Use Dijkstra for root distances and Prim/Kruskal for total connection cost.',
        ],
        '≠',
        [],
        'none'
      );
    }

    if (has('mst-baseline') && has('minimum-edge-tree')) {
      return mstRelation(
        'Naive greedy trap',
        'mst-warning-link',
        'Picking light edges is not enough unless the forest invariant and cycle test are part of the rule.',
        'cheap-looking edges ≠ safe greedy construction',
        'The algorithmic proof is doing real work: it says which cheap edges are allowed.',
        'Kruskal is correct because it rejects cycle-forming edges and maintains extendability to an MST.',
        [
          'A globally light edge can be useless if it closes a cycle inside the current forest.',
          'A sequence of locally tempting choices can strand vertices or require expensive repairs.',
          'The cut/safe-edge invariant is the missing proof obligation.',
        ],
        '≠',
        [],
        'none'
      );
    }

    if (has('mst-baseline') && has('clustering')) {
      return mstRelation(
        'Kruskal clustering consequence',
        'mst-consequence-link',
        'Stopping Kruskal early gives the maximum-spacing k-clustering theorem.',
        'Kruskal forest at k components -> next safe edge determines spacing',
        'The same sorted-edge logic explains both MST construction and hierarchical clustering.',
        'This is a theorem derived from Kruskal logic, not an equivalent definition of MST.',
        [
          'Run Kruskal until exactly k components remain.',
          'Any clustering with larger spacing would have to avoid all edges lighter than that spacing.',
          'Kruskal has already used every necessary lighter connection, so the produced clustering maximizes spacing.',
        ],
        '→',
        [],
        'forward'
      );
    }
  }

  return mstRelation(
    'MST bridge',
    'mst-proof-route',
    'These statements are linked by cut, cycle, exchange, or greedy reasoning.',
    `${a.title} -> MST proof hub -> ${b.title}`,
    'The relation is best understood by choosing the proof invariant that survives the move.',
    'Check the active world legend to see whether this edge is equivalence, proof comparison, or variant comparison.',
    [
      `Start with ${a.title}.`,
      'Move through the MST proof hub: cut, cycle, exchange, or greedy invariant.',
      `Compare the result with ${b.title}.`,
    ],
    '⇄'
  );
}

function getMstArrowMode(relation) {
  if (relation.arrow) return relation.arrow;
  if ((relation.signal || '').includes('↔') || (relation.signal || '').includes('⇄')) return 'both';
  if ((relation.signal || '').includes('←') || (relation.signal || '').includes('⇐')) return 'backward';
  if ((relation.signal || '').includes('→') || (relation.signal || '').includes('⇒')) return 'forward';
  if ((relation.signal || '').includes('≠')) return 'none';
  if (relation.kind === 'mst-equivalent') return 'both';
  if (relation.kind === 'mst-warning-link') return 'none';
  return 'forward';
}

function mstEdgeSignalLabel(relation) {
  const mode = getMstArrowMode(relation);
  if (mode === 'both') return '↔';
  if (mode === 'backward') return '←';
  if (mode === 'none') return '≠';
  return '→';
}

function mstGraphSignal(relation) {
  const signal = mstEdgeSignalLabel(relation);
  return signal === '↔' ? '⇄' : signal;
}

