function renderNoiseBridgeDemo(relation, a, b) {
  const mode = noiseBridgeMode(relation);
  return `
    <div class="noise-demo-title">${relation.type}</div>
    <svg class="noise-demo-svg" viewBox="0 0 360 220" role="img" aria-label="Noise bridge">
      <rect class="noise-bridge-box left" x="24" y="68" width="118" height="78" rx="20" />
      <rect class="noise-bridge-box right" x="218" y="68" width="118" height="78" rx="20" />
      <path class="noise-bridge-arc upper ${mode}" d="M142 84 C166 50 194 50 218 84" />
      <path class="noise-bridge-arc lower ${mode}" d="M218 130 C194 166 166 166 142 130" />
      ${noiseBridgeArrowHead({ x: 218, y: 84 }, { x: 24, y: 34 }, 'upper', mode)}
      ${mode === 'identity' || mode === 'scope' ? noiseBridgeArrowHead({ x: 142, y: 130 }, { x: -24, y: -34 }, 'lower', mode) : ''}
      <text class="noise-bridge-side left" x="83" y="92" text-anchor="middle">from</text>
      <text class="noise-bridge-side right" x="277" y="92" text-anchor="middle">to</text>
      ${renderNoiseBridgeLabel(a.title, 83, 116, 'left')}
      ${renderNoiseBridgeLabel(b.title, 277, 116, 'right')}
      <text class="noise-bridge-proof upper" x="180" y="42" text-anchor="middle">∵ ${noiseBridgeUpperLabel(mode)}</text>
      <text class="noise-bridge-proof lower" x="180" y="190" text-anchor="middle">${noiseBridgeLowerLabel(mode)}</text>
      <circle class="noise-bridge-dot" cx="180" cy="108" r="12" />
      <text class="noise-bridge-dot-label" x="180" y="112" text-anchor="middle">${noiseEdgeSignalLabel(relation)}</text>
    </svg>
  `;
}

function noiseBridgeMode(relation) {
  if (relation.kind === 'noise-warning-link') return 'warning';
  if (relation.kind === 'noise-equivalent') return 'identity';
  if (relation.kind === 'noise-scope-link') return 'scope';
  if (relation.kind === 'noise-formula' || relation.kind === 'noise-parameter') return 'formula';
  return 'construction';
}

function noiseBridgeUpperLabel(mode) {
  const labels = {
    construction: 'build the next object',
    identity: 'same law under scope',
    formula: 'read the exponent',
    scope: 'diagnostic bridge',
    warning: 'false transfer',
  };
  return labels[mode] || 'noise route';
}

function noiseBridgeLowerLabel(mode) {
  const labels = {
    construction: '∴ recipe route',
    identity: '∴ same model face',
    formula: '∴ parameter relation',
    scope: 'related, not complete',
    warning: 'check the law',
  };
  return labels[mode] || 'compare definitions';
}

function noiseBridgeArrowHead(tip, tangent, className, mode) {
  const length = 13;
  const width = 11;
  const norm = Math.hypot(tangent.x, tangent.y) || 1;
  const unit = { x: tangent.x / norm, y: tangent.y / norm };
  const perp = { x: -unit.y, y: unit.x };
  const base = {
    x: tip.x - unit.x * length,
    y: tip.y - unit.y * length,
  };
  const left = {
    x: base.x + perp.x * width * 0.58,
    y: base.y + perp.y * width * 0.58,
  };
  const right = {
    x: base.x - perp.x * width * 0.58,
    y: base.y - perp.y * width * 0.58,
  };
  return `
    <path
      class="noise-bridge-arrowhead ${className} ${mode}"
      d="M ${tip.x} ${tip.y} L ${left.x.toFixed(1)} ${left.y.toFixed(1)} Q ${base.x.toFixed(1)} ${base.y.toFixed(1)} ${right.x.toFixed(1)} ${right.y.toFixed(1)} Z"
    />
  `;
}

function renderNoiseBridgeLabel(label, x, y, className) {
  const lines = operatorBridgeLabelLines(label, 2, 14);
  return `
    <text class="noise-bridge-title ${className}" x="${x}" y="${y}" text-anchor="middle">
      ${lines
        .map((line, index) => `<tspan x="${x}" dy="${index === 0 ? 0 : 15}">${line}</tspan>`)
        .join('')}
    </text>
  `;
}

function noiseBars(values, x, baseline, className = 'blue') {
  const width = 14;
  const gap = 8;
  return values
    .map((value, index) => {
      const height = Math.abs(baseline - value);
      const y = Math.min(value, baseline);
      return `<rect class="noise-bar ${className}" x="${x + index * (width + gap)}" y="${y}" width="${width}" height="${height}" rx="5" />`;
    })
    .join('');
}

function noiseLatticeDots() {
  const points = [
    [72, 72],
    [132, 72],
    [192, 72],
    [252, 72],
    [72, 132],
    [132, 132],
    [192, 132],
    [252, 132],
  ];
  return points.map(([x, y], index) => `<circle class="noise-dot ${index % 2 ? 'alt' : ''}" cx="${x}" cy="${y}" r="7" />`).join('');
}

function noiseBlueDots() {
  const points = [
    [72, 86],
    [104, 128],
    [144, 82],
    [178, 142],
    [214, 94],
    [252, 132],
    [292, 82],
    [82, 166],
    [132, 162],
    [230, 168],
  ];
  return points.map(([x, y]) => `<circle class="noise-dot blue-noise-dot" cx="${x}" cy="${y}" r="5.5" />`).join('');
}

function noiseGradientTicks() {
  const ticks = [
    [74, 78, 18, -12],
    [132, 82, -14, -16],
    [190, 76, 16, 14],
    [250, 84, -12, 16],
    [84, 144, 20, 10],
    [158, 148, -16, 14],
    [230, 142, 16, -16],
  ];
  return ticks
    .map(
      ([x, y, dx, dy], index) => `
        <circle class="noise-dot ${index % 2 ? 'alt' : ''}" cx="${x}" cy="${y}" r="5" />
        <path class="noise-gradient-tick" d="M${x} ${y} l${dx} ${dy}" />
      `
    )
    .join('');
}

function getIntegralEdgeId(edge) {
  return `${edge.from}__${edge.to}`;
}

function parseIntegralEdge(edgeId) {
  if (!edgeId) return null;
  return integralEdges.find((edge) => getIntegralEdgeId(edge) === edgeId) || null;
}

function renderIntegralSection() {
  if (!elements.integralMap) return;

  const selectedNode = integralNodeMap[state.selectedIntegralNodeId] || integralNodes[0];
  const selectedEdge = parseIntegralEdge(state.selectedIntegralEdge);

  state.selectedIntegralNodeId = selectedNode.id;
  if (state.selectedIntegralEdge && !selectedEdge) {
    state.selectedIntegralEdge = null;
  }

  elements.integralNote.innerHTML = `
    <p>
      Read an arrow <strong>A ⊂ B</strong> as “every A-integrable example in the stated scope is B-integrable,
      and the values agree.” Warning edges mark places where two notions compare only after adding hypotheses.
    </p>
    ${renderIntegralLegend()}
  `;

  elements.integralMap.innerHTML = renderIntegralMap(selectedNode, selectedEdge);
  elements.integralBridgeList.innerHTML = integralEdges
    .map((edge) => {
      const from = integralNodeMap[edge.from];
      const to = integralNodeMap[edge.to];
      if (!from || !to) return '';
      const fromFamily = integralFamilyMeta[from.family] || integralFamilyMeta.classical;
      const toFamily = integralFamilyMeta[to.family] || integralFamilyMeta.measure;
      const edgeId = getIntegralEdgeId(edge);
      return `
        <button class="integral-edge-chip ${edge.kind} ${state.selectedIntegralEdge === edgeId ? 'is-active' : ''}" data-integral-edge="${edgeId}">
          <span><i class="integral-mini-symbol ${fromFamily.className}">${from.symbol || ''}</i>${from.title}</span>
          <strong>${integralEdgeSignalLabel(edge)} ${edge.type}</strong>
          <span><i class="integral-mini-symbol ${toFamily.className}">${to.symbol || ''}</i>${to.title}</span>
        </button>
      `;
    })
    .join('');

  elements.integralDetail.innerHTML = selectedEdge
    ? renderIntegralRelationDetail(selectedEdge)
    : renderIntegralNodeDetail(selectedNode);
  scheduleBridgeListBalance();
}

function renderIntegralLegend() {
  const families = [...new Set(integralNodes.map((node) => node.family))];
  return `
    <div class="integral-legend" aria-label="Integral family legend">
      ${families
        .map((familyId) => {
          const family = integralFamilyMeta[familyId] || integralFamilyMeta.classical;
          return `
            <span class="integral-legend-item ${family.className}">
              <i aria-hidden="true"></i>
              <strong>${family.label}</strong>
              <em>${integralFamilyNote(familyId)}</em>
            </span>
          `;
        })
        .join('')}
    </div>
    <div class="integral-relation-legend" aria-label="Integral relation legend">
      <span><i class="extension"></i>⊂ means extension under the written scope</span>
      <span><i class="equivalence"></i>↔ means same admitted functions there</span>
      <span><i class="criterion"></i>L¹ / abs means a criterion or sufficient condition</span>
      <span><i class="warning"></i>≠ means similar-looking notions diverge</span>
    </div>
  `;
}

function integralFamilyNote(familyId) {
  const notes = {
    classical: 'bounded interval sums',
    limit: 'singular or infinite limits',
    measure: 'measurable mass',
    gauge: 'adaptive tagged sums',
    weighted: 'custom measuring stick',
    weak: 'test-function action',
    criterion: 'admission test',
  };
  return notes[familyId] || 'integral face';
}

function renderIntegralMap(selectedNode, selectedEdge) {
  const selectedEdgeId = selectedEdge ? getIntegralEdgeId(selectedEdge) : null;
  const edgeItems = integralEdges.map((edge, index) => {
    const start = integralNodeMap[edge.from];
    const end = integralNodeMap[edge.to];
    const edgeId = getIntegralEdgeId(edge);
    const isSelectedEdge = edgeId === selectedEdgeId;
    const touchesSelectedNode = edge.from === selectedNode.id || edge.to === selectedNode.id;
    const isActive = isSelectedEdge || (!selectedEdgeId && touchesSelectedNode);
    const signalClass = isSelectedEdge ? 'is-active' : !selectedEdgeId && touchesSelectedNode ? 'is-node-active' : '';
    return {
      edge,
      edgeId,
      curve: getIntegralCurvePath(start, end, index),
      isActive,
      signalClass,
    };
  });

  return `
    <div class="integral-orbit">
      <svg class="integral-complete-svg" viewBox="0 0 100 100" role="img" aria-label="Integral definition comparison graph">
        ${edgeItems
          .map(
            ({ edge, edgeId, curve, isActive, signalClass }) => `
              ${renderIntegralEdgeHitbox(curve, edgeId)}
              ${renderIntegralEdgeLine(curve, edge, edgeId, isActive)}
              ${renderIntegralEdgeSignalMarker(curve, edge, edgeId, signalClass)}
            `
          )
          .join('')}
      </svg>
      ${integralNodes
        .map((node) => {
          const family = integralFamilyMeta[node.family] || integralFamilyMeta.classical;
          const isEndpoint = selectedEdge && (selectedEdge.from === node.id || selectedEdge.to === node.id);
          return `
            <button
              class="integral-node ${family.className} ${node.id === selectedNode.id && !selectedEdgeId ? 'is-active' : ''} ${isEndpoint ? 'is-endpoint' : ''}"
              data-integral-node="${node.id}"
              style="left: ${node.x}%; top: ${node.y}%;"
              aria-label="${node.title}: ${family.label}"
            >
              <span class="integral-symbol">${node.symbol || ''}</span>
              <strong>${node.title}</strong>
              <small>${family.label}</small>
            </button>
          `;
        })
        .join('')}
    </div>
  `;
}

function getIntegralCurvePath(start, end, index) {
  const center = { x: 50, y: 52 };
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const length = Math.hypot(dx, dy) || 1;
  const perpendicular = { x: -dy / length, y: dx / length };
  const lane = ((index % 5) - 2) * 1.2;
  const laneOffset = {
    x: perpendicular.x * lane,
    y: perpendicular.y * lane,
  };
  const pull = 0.54;
  const controlStart = {
    x: start.x + (center.x - start.x) * pull + laneOffset.x,
    y: start.y + (center.y - start.y) * pull + laneOffset.y,
  };
  const controlEnd = {
    x: end.x + (center.x - end.x) * pull + laneOffset.x,
    y: end.y + (center.y - end.y) * pull + laneOffset.y,
  };
  const markerT = [0.48, 0.55, 0.43, 0.6, 0.38][index % 5];
  const marker = cubicPoint(start, controlStart, controlEnd, end, markerT);
  const tangent = cubicTangent(start, controlStart, controlEnd, end, markerT);
  const angle = (Math.atan2(tangent.y, tangent.x) * 180) / Math.PI;
  const d = `M ${start.x.toFixed(2)} ${start.y.toFixed(2)} C ${controlStart.x.toFixed(2)} ${controlStart.y.toFixed(2)} ${controlEnd.x.toFixed(2)} ${controlEnd.y.toFixed(2)} ${end.x.toFixed(2)} ${end.y.toFixed(2)}`;
  return { d, marker, angle };
}

function renderIntegralEdgeHitbox(curve, edgeId) {
  return `<path class="integral-edge-hitbox" d="${curve.d}" data-integral-edge="${edgeId}" />`;
}

function renderIntegralEdgeLine(curve, edge, edgeId, isActive) {
  return `<path class="integral-edge ${edge.kind} ${isActive ? 'is-active' : ''}" d="${curve.d}" data-integral-edge="${edgeId}" />`;
}

function renderIntegralEdgeSignalMarker(curve, edge, edgeId, stateClass = '') {
  const x = curve.marker.x.toFixed(2);
  const y = curve.marker.y.toFixed(2);
  const angle = curve.angle.toFixed(2);
  return `
    <g class="integral-edge-signal ${edge.kind} ${stateClass}" data-integral-edge="${edgeId}" transform="translate(${x} ${y}) rotate(${angle})">
      <circle cx="0" cy="0" r="3.45" />
      <text x="0" y="0.95" text-anchor="middle" transform="rotate(${(-Number(angle)).toFixed(2)})">${integralGraphSignal(edge)}</text>
    </g>
  `;
}

function integralEdgeSignalLabel(edge) {
  return edge.signal || '→';
}

function integralGraphSignal(edge) {
  const signal = integralEdgeSignalLabel(edge);
  if (signal === 'μα') return 'μ';
  if (signal.length > 3) return signal.slice(0, 3);
  return signal;
}

function renderIntegralNodeDetail(node) {
  const family = integralFamilyMeta[node.family] || integralFamilyMeta.classical;
  return `
    <p class="eyebrow">Integral definition</p>
    <div class="badge-row">
      ${renderBadge('integrability scope', 'integral-world')}
      ${renderBadge(family.label, family.className)}
    </div>
    <h2 class="detail-title integral-title-with-symbol"><span class="${family.className}">${node.symbol || ''}</span>${node.title}</h2>
    <p class="detail-summary">${node.short}</p>
    <div class="integral-demo-card">
      ${renderIntegralDemo(node.demo, node.title)}
    </div>
    <div class="detail-block integral-definition-block">
      <h3>Formal read</h3>
      <p>${node.definition}</p>
    </div>
    <div class="detail-grid">
      <div class="fact">
        <span class="fact-label">Integrable objects</span>
        <span class="fact-value">${node.integrable}</span>
      </div>
      <div class="fact">
        <span class="fact-label">Witness data</span>
        <span class="fact-value">${node.witness}</span>
      </div>
    </div>
    ${renderIntegralTermList(getIntegralNodeTerms(node))}
    <div class="detail-block">
      <h3>Intuition</h3>
      <p>${node.intuition}</p>
    </div>
    <div class="detail-block">
      <h3>Proof role</h3>
      <p>${node.proof}</p>
    </div>
  `;
}

function renderIntegralRelationDetail(edge) {
  const from = integralNodeMap[edge.from];
  const to = integralNodeMap[edge.to];
  if (!from || !to) return renderIntegralNodeDetail(integralNodes[0]);
  const fromFamily = integralFamilyMeta[from.family] || integralFamilyMeta.classical;
  const toFamily = integralFamilyMeta[to.family] || integralFamilyMeta.measure;
  return `
    <p class="eyebrow">Integral comparison bridge</p>
    <div class="badge-row">
      ${renderBadge(edge.type, edge.kind)}
      ${renderBadge(integralRelationModeLabel(edge), 'integral-world')}
    </div>
    <h2 class="integral-relation-title">
      <span class="${fromFamily.className}">${from.symbol || ''}</span>
      ${from.title}
      <em>${integralEdgeSignalLabel(edge)}</em>
      <span class="${toFamily.className}">${to.symbol || ''}</span>
      ${to.title}
    </h2>
    <p class="detail-summary">${edge.summary}</p>
    <div class="integral-demo-card">
      ${renderIntegralBridgeDemo(edge, from, to)}
    </div>
    ${renderIntegralRouteStrip(edge)}
    ${renderIntegralTermList(getIntegralRelationTerms(from, to, edge))}
    ${renderIntegralProofSteps(edge.steps || [])}
    <div class="detail-grid">
      <div class="fact">
        <span class="fact-label">Left admits</span>
        <span class="fact-value">${from.integrable}</span>
      </div>
      <div class="fact">
        <span class="fact-label">Right admits</span>
        <span class="fact-value">${to.integrable}</span>
      </div>
    </div>
    <div class="detail-block">
      <h3>What changes in your head</h3>
      <p>${edge.takeaway}</p>
    </div>
    <div class="detail-block">
      <h3>Scope note</h3>
      <p>${edge.caveat}</p>
    </div>
  `;
}

function integralRelationModeLabel(edge) {
  if (edge.kind === 'integral-equivalent') return 'same integrable class';
  if (edge.kind === 'integral-extension') return 'extension route';
  if (edge.kind === 'integral-warning-link') return 'scope warning';
  if (edge.kind === 'integral-criterion') return 'criterion route';
  if (edge.kind === 'integral-weak-link') return 'weak route';
  return 'change of measure';
}

function renderIntegralRouteStrip(edge) {
  return `
    <div class="integral-route-strip">
      <span>${integralRelationModeLabel(edge)}</span>
      <p>${edge.route}</p>
    </div>
  `;
}

function renderIntegralProofSteps(steps = []) {
  if (!steps.length) return '';
  return `
    <div class="integral-proof-lines" aria-label="Integral proof steps">
      ${steps
        .map(
          (step, index, list) => `
            <div class="integral-proof-line">
              <span>${fractalProofLineSymbol(index, list.length)}</span>
              <p>${step}</p>
            </div>
          `
        )
        .join('')}
    </div>
  `;
}

function renderIntegralTermList(terms = []) {
  if (!terms.length) return '';
  return `
    <div class="integral-term-list" aria-label="Integral concept definitions">
      ${terms
        .map(
          (item) => `
            <div class="integral-term">
              <strong>${item.term}</strong>
              <p>${item.definition}</p>
            </div>
          `
        )
        .join('')}
    </div>
  `;
}

function getIntegralNodeTerms(node) {
  const familyTerms = {
    classical: [{ term: 'Partition logic', definition: 'The integral is controlled by chopping the domain into intervals.' }],
    limit: [{ term: 'Limit definition', definition: 'The integral is accepted only after a truncation limit exists.' }],
    measure: [{ term: 'Almost everywhere', definition: 'Measure-zero exceptions do not change the Lebesgue integral.' }],
    gauge: [{ term: 'Adaptive fineness', definition: 'The allowed interval size changes from point to point.' }],
    weighted: [{ term: 'Weighted mass', definition: 'The measuring rule is not ordinary length.' }],
    weak: [{ term: 'Dual action', definition: 'The object is understood by how it acts on probes.' }],
    criterion: [{ term: 'Sufficient test', definition: 'A condition used to guarantee integrability or convergence.' }],
  };
  return [...(node.terms || []), ...(familyTerms[node.family] || [])];
}

function getIntegralRelationTerms(from, to, edge) {
  const terms = [...getIntegralNodeTerms(from), ...getIntegralNodeTerms(to)];
  if (edge.kind === 'integral-extension') {
    terms.push({
      term: 'Extension',
      definition:
        'An extension preserves old values while admitting a larger or differently scoped class of functions.',
    });
  }
  if (edge.kind === 'integral-warning-link') {
    terms.push({
      term: 'False converse',
      definition:
        'A convergent signed limit can look like integrability while failing the absolute or measure-theoretic condition.',
    });
  }
  if (edge.kind === 'integral-weak-link') {
    terms.push({
      term: 'Weak equality',
      definition:
        'Two objects may be compared by test-function pairings even when pointwise comparison is unavailable.',
    });
  }
  const seen = new Set();
  return terms.filter((term) => {
    if (seen.has(term.term)) return false;
    seen.add(term.term);
    return true;
  });
}

