function renderComplexTrigAside(theorem) {
  if (!['static', 'complex'].includes(theorem.family)) return '';
  return `
    <aside class="field-trig-aside">
      <div>
        <span>complex proof taste</span>
        <strong>e<sup>i(a+b)</sup> = e<sup>ia</sup>e<sup>ib</sup></strong>
        <p>
          Expanding both sides gives cos(a+b) and sin(a+b) almost for free.
          Geometry still explains why rotations compose; complex notation makes the algebra one line.
        </p>
      </div>
      <code>
        cos(a+b)=cos a cos b - sin a sin b<br />
        sin(a+b)=sin a cos b + cos a sin b
      </code>
    </aside>
  `;
}

function renderFieldTermList(terms = []) {
  return `
    <div class="field-term-list" aria-label="Field integral definitions">
      ${terms
        .map(
          (item) => `
            <div class="field-term">
              <strong>${item.term}</strong>
              <p>${item.definition}</p>
            </div>
          `
        )
        .join('')}
    </div>
  `;
}

function renderFieldComparison(card) {
  const other = fieldIntegralCards.find((item) => item.id !== card.id);
  if (!other) return '';
  return `
    <div class="field-comparison">
      <span class="field-comparison-pill">${card.symbol}</span>
      <div>
        <strong>${card.title}</strong>
        <p>${card.id === 'moving-domain-transport' ? 'adds time and boundary motion to the static integral language.' : 'provides the geometric integral language that transport rules differentiate.'}</p>
      </div>
      <span class="field-comparison-arrow">→</span>
      <span class="field-comparison-pill alt">${other.symbol}</span>
      <button data-field-card="${other.id}">${other.title}</button>
    </div>
  `;
}

