function renderCounterexampleSection() {
  if (!elements.counterexampleList) return;

  const selected =
    counterexampleSpaces.find((space) => space.id === state.selectedCounterexampleId) || counterexampleSpaces[0];
  state.selectedCounterexampleId = selected?.id ?? null;

  elements.counterexampleList.innerHTML = counterexampleSpaces
    .map(
      (space) => `
        <button class="counterexample-card ${space.id === state.selectedCounterexampleId ? 'is-active' : ''}" data-counterexample-id="${space.id}">
          <div class="badge-row">
            ${renderBadge(space.theme, 'counterexample-theme')}
          </div>
          <h3>${space.name}</h3>
          <p>${space.short}</p>
          <span>${space.separates}</span>
        </button>
      `
    )
    .join('');

  if (!selected) {
    elements.counterexampleDetail.innerHTML = '';
    return;
  }

  elements.counterexampleDetail.innerHTML = `
    <p class="eyebrow">Counterexample topology</p>
    <div class="badge-row">
      ${renderBadge(selected.theme, 'counterexample-theme')}
      ${renderBadge(selected.source, 'counterexample-source')}
    </div>
    <h2 class="detail-title">${selected.name}</h2>
    <p class="detail-summary">${selected.short}</p>
    <div class="counterexample-split">
      <div>
        <span class="fact-label">Has</span>
        <div class="counterexample-badges">
          ${renderCounterexamplePropertyChips(selected.has, 'has')}
        </div>
      </div>
      <div>
        <span class="fact-label">Fails</span>
        <div class="counterexample-badges">
          ${renderCounterexamplePropertyChips(selected.lacks, 'lacks')}
        </div>
      </div>
    </div>
    <div class="detail-block counterexample-break">
      <h3>Breaks this tempting implication</h3>
      <p>${selected.separates}</p>
    </div>
    <div class="detail-block">
      <h3>Construction</h3>
      <p>${selected.construction}</p>
    </div>
    <div class="detail-block">
      <h3>Lesson</h3>
      <p>${selected.lesson}</p>
    </div>
    <div class="detail-block">
      <h3>What to watch</h3>
      <p>${selected.watch}</p>
    </div>
    <div class="detail-block">
      <h3>Why this panel exists</h3>
      <p>These examples are used as proof guards: every time two definitions feel interchangeable, a counterexample asks which hidden hypothesis made the implication true.</p>
    </div>
  `;
}

function renderCounterexamplePropertyChips(ids = [], mode = 'has') {
  return ids
    .map((id) => {
      const axiom = axiomLookup[id];
      if (axiom) {
        return `<button class="counterexample-chip ${mode}" data-axiom-id="${axiom.id}">${axiom.symbol}: ${axiom.name}</button>`;
      }
      const concept = conceptMap[id];
      if (concept) {
        return `<button class="counterexample-chip ${mode}" data-concept-id="${concept.id}" data-jump="true">${concept.name}</button>`;
      }
      return `<span class="counterexample-chip ${mode}">${counterexampleLooseLabel(id)}</span>`;
    })
    .join('');
}

function counterexampleLooseLabel(id) {
  const labels = {
    compactness: 'Compact',
    metrization: 'Metrizable',
    'local-compactness': 'Locally compact',
    'first-countable': 'First countable',
    'second-countable': 'Second countable',
    'lindelof-separable': 'Lindelof / separable',
    lindelof: 'Lindelof',
    separable: 'Separable',
  };
  return labels[id] || id;
}

