function startHeroMesh() {
  const canvas = elements.heroMesh;
  if (!canvas || window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    return;
  }

  const context = canvas.getContext('2d');
  const points = Array.from({ length: 28 }, () => ({
    x: Math.random(),
    y: Math.random(),
    vx: (Math.random() - 0.5) * 0.0018,
    vy: (Math.random() - 0.5) * 0.0018,
    size: 1.5 + Math.random() * 2.5,
  }));

  let width = 0;
  let height = 0;

  function resize() {
    const rect = canvas.getBoundingClientRect();
    width = rect.width;
    height = rect.height;
    const scale = window.devicePixelRatio || 1;
    canvas.width = width * scale;
    canvas.height = height * scale;
    context.setTransform(scale, 0, 0, scale, 0, 0);
  }

  function draw() {
    context.clearRect(0, 0, width, height);

    for (const point of points) {
      point.x += point.vx;
      point.y += point.vy;

      if (point.x <= 0 || point.x >= 1) point.vx *= -1;
      if (point.y <= 0 || point.y >= 1) point.vy *= -1;
    }

    for (let i = 0; i < points.length; i += 1) {
      for (let j = i + 1; j < points.length; j += 1) {
        const a = points[i];
        const b = points[j];
        const dx = (a.x - b.x) * width;
        const dy = (a.y - b.y) * height;
        const distance = Math.hypot(dx, dy);
        if (distance < 140) {
          context.strokeStyle = `rgba(126, 195, 228, ${0.18 - distance / 1000})`;
          context.lineWidth = 1;
          context.beginPath();
          context.moveTo(a.x * width, a.y * height);
          context.lineTo(b.x * width, b.y * height);
          context.stroke();
        }
      }
    }

    for (const point of points) {
      context.fillStyle = 'rgba(255, 200, 121, 0.95)';
      context.beginPath();
      context.arc(point.x * width, point.y * height, point.size, 0, Math.PI * 2);
      context.fill();
    }

    requestAnimationFrame(draw);
  }

  window.addEventListener('resize', resize);
  resize();
  draw();
}

// ===== Generic concept-zoo engine (orbit graph) =====
// Powers the new zoos (AC-equivalents, induction, complexity, convergence,
// Gauss-Bonnet, spectral). Each zoo is data only; this engine renders the
// orbit graph, bridge list, and detail panel, reusing the relation legend.
const zooRegistry = {};

const ZOO_RELATION_LABELS = {
  equivalence: 'equivalent',
  consequence: 'one-way consequence',
  scope: 'scope / condition',
  warning: 'false friend / weaker',
  open: 'open / conjectured',
};

function defineZooGraph(config) {
  config.nodeMap = Object.fromEntries(config.nodes.map((node) => [node.id, node]));
  config.familyMap = Object.fromEntries((config.families || []).map((family) => [family.id, family]));
  config.selectedNodeId = config.nodes[0] ? config.nodes[0].id : null;
  config.selectedEdge = null;
  config.el = {
    note: document.getElementById(config.id + 'Note'),
    map: document.getElementById(config.id + 'Map'),
    bridgeList: document.getElementById(config.id + 'BridgeList'),
    detail: document.getElementById(config.id + 'Detail'),
  };
  zooRegistry[config.id] = config;
  return config;
}

function getZooEdgeId(edge) {
  return `${edge.from}__${edge.to}__${edge.kind}`;
}

function getZooCurve(from, to, index) {
  const midX = (from.x + to.x) / 2;
  const midY = (from.y + to.y) / 2;
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  const length = Math.hypot(dx, dy) || 1;
  const nx = -dy / length;
  const ny = dx / length;
  const towardCenter = (50 - midX) * nx + (50 - midY) * ny >= 0 ? 1 : -1;
  const bend = 8 + (index % 4) * 2.4;
  const control = { x: midX + nx * bend * towardCenter, y: midY + ny * bend * towardCenter };
  return {
    control,
    path: `M ${from.x.toFixed(2)} ${from.y.toFixed(2)} Q ${control.x.toFixed(2)} ${control.y.toFixed(2)} ${to.x.toFixed(2)} ${to.y.toFixed(2)}`,
  };
}

function zooQuadraticPoint(from, control, to, t) {
  const s = 1 - t;
  return {
    x: (s * s * from.x + 2 * s * t * control.x + t * t * to.x).toFixed(2),
    y: (s * s * from.y + 2 * s * t * control.y + t * t * to.y).toFixed(2),
  };
}

function renderZooMap(config, selectedNode, selectedEdge) {
  const selectedEdgeId = selectedEdge ? getZooEdgeId(selectedEdge) : null;
  const radius = 38;
  const positions = config.nodes.map((node, index) => {
    const angle = -Math.PI / 2 + (Math.PI * 2 * index) / config.nodes.length;
    return { ...node, x: 50 + radius * Math.cos(angle), y: 50 + radius * Math.sin(angle) };
  });
  const positionMap = Object.fromEntries(positions.map((node) => [node.id, node]));
  const edgeItems = config.edges
    .map((edge, index) => {
      const from = positionMap[edge.from];
      const to = positionMap[edge.to];
      if (!from || !to) return null;
      const edgeId = getZooEdgeId(edge);
      const isSelectedEdge = edgeId === selectedEdgeId;
      const touchesSelectedNode = edge.from === selectedNode.id || edge.to === selectedNode.id;
      const isActive = isSelectedEdge || (!selectedEdgeId && touchesSelectedNode);
      const signalClass = isSelectedEdge ? 'is-active' : !selectedEdgeId && touchesSelectedNode ? 'is-node-active' : '';
      const curve = getZooCurve(from, to, index);
      const point = zooQuadraticPoint(from, curve.control, to, 0.5);
      return { edge, edgeId, isActive, signalClass, curve, point };
    })
    .filter(Boolean);

  return `
    <div class="zoo-orbit">
      <svg class="zoo-complete-svg" viewBox="0 0 100 100" aria-hidden="true">
        ${edgeItems
          .map(
            ({ edge, edgeId, isActive, curve }) => `
              <path class="zoo-edge-hitbox" d="${curve.path}" data-zoo="${config.id}" data-zoo-edge="${edgeId}"></path>
              <path class="zoo-edge zoo-${edge.kind} ${isActive ? 'is-active' : ''}" d="${curve.path}" data-zoo="${config.id}" data-zoo-edge="${edgeId}"></path>
            `
          )
          .join('')}
        ${edgeItems
          .map(
            ({ edge, edgeId, signalClass, point }) => `
              <g class="zoo-edge-signal zoo-${edge.kind} ${signalClass}" data-zoo="${config.id}" data-zoo-edge="${edgeId}" transform="translate(${point.x} ${point.y})">
                <circle r="4.7"></circle>
                <text text-anchor="middle">${edge.signal}</text>
              </g>
            `
          )
          .join('')}
      </svg>
      ${positions
        .map((node) => {
          const family = config.familyMap[node.family];
          const isEndpoint = selectedEdge && (selectedEdge.from === node.id || selectedEdge.to === node.id);
          return `
            <button
              class="zoo-node ${node.id === selectedNode.id && !selectedEdgeId ? 'is-active' : ''} ${isEndpoint ? 'is-endpoint' : ''}"
              style="left:${node.x}%; top:${node.y}%"
              data-zoo="${config.id}"
              data-zoo-node="${node.id}"
            >
              <span>${node.symbol}</span>
              <strong>${node.title}</strong>
              ${family ? `<small>${family.label}</small>` : ''}
            </button>
          `;
        })
        .join('')}
    </div>
  `;
}

function renderZooNodeDetail(config, node) {
  const family = config.familyMap[node.family];
  const connected = config.edges.filter((edge) => edge.from === node.id || edge.to === node.id);
  return `
    <div class="detail-badges">
      ${family ? renderBadge(family.label, 'zoo-tag') : ''}
      ${renderBadge('proof zoo', 'zoo-tag')}
    </div>
    <h2 class="detail-title trig-title-with-symbol"><span class="zoo-symbol">${node.symbol}</span>${node.title}</h2>
    <p class="detail-summary">${node.short}</p>
    <div class="detail-block"><h3>Definition</h3><p>${node.definition}</p></div>
    <div class="detail-block"><h3>Intuition</h3><p>${node.intuition}</p></div>
    <div class="zoo-watch"><strong>Watch</strong><p>${node.watch}</p></div>
    <section class="trig-connected">
      <h3>Connected bridges</h3>
      <div>
        ${connected
          .map((edge) => {
            const other = config.nodeMap[edge.from === node.id ? edge.to : edge.from];
            return `<button class="zoo-${edge.kind}" data-zoo="${config.id}" data-zoo-edge="${getZooEdgeId(edge)}"><span>${edge.signal}</span>${other.title}</button>`;
          })
          .join('')}
      </div>
    </section>
  `;
}

function renderZooRelationDetail(config, edge) {
  const from = config.nodeMap[edge.from];
  const to = config.nodeMap[edge.to];
  return `
    <div class="detail-badges">
      ${renderBadge(ZOO_RELATION_LABELS[edge.kind] || 'bridge', 'zoo-' + edge.kind)}
      ${renderBadge(edge.signal, 'zoo-tag')}
    </div>
    <h2 class="detail-title">Bridge: ${from.symbol} ${edge.signal} ${to.symbol}</h2>
    <p class="detail-summary">${edge.summary}</p>
    <div class="trig-route-card"><span>route</span><strong>${edge.route}</strong></div>
    <section class="trig-proof-routes">
      <h3>Proof sketch</h3>
      ${edge.steps
        .map(
          (step, index) => `
            <div class="trig-proof-line">
              <span>${index === 0 ? '∵' : index === edge.steps.length - 1 ? '∴' : '⇒'}</span>
              <p>${step}</p>
            </div>
          `
        )
        .join('')}
    </section>
    <div class="trig-two-column">
      <article><span>left</span><strong>${from.title}</strong><p>${from.short}</p></article>
      <article><span>right</span><strong>${to.title}</strong><p>${to.short}</p></article>
    </div>
    <div class="trig-payoff"><strong>Takeaway</strong><p>${edge.takeaway}</p></div>
    <div class="trig-caveat zoo-${edge.kind}"><strong>Caveat</strong><p>${edge.caveat}</p></div>
  `;
}

function renderZooGraphSection(id) {
  const config = zooRegistry[id];
  if (!config || !config.el.map) return;
  const selectedNode = config.nodeMap[config.selectedNodeId] || config.nodes[0];
  const selectedEdge = config.edges.find((edge) => getZooEdgeId(edge) === config.selectedEdge) || null;
  config.selectedNodeId = selectedNode.id;

  config.el.note.innerHTML = `
    <p><strong>Read it:</strong> pick a node for its definition, or a bridge for its proof route. The edge colour encodes the relation type.</p>
    <div class="zoo-relation-legend">
      <span><i class="equivalence"></i> equivalent (↔)</span>
      <span><i class="consequence"></i> one-way (→)</span>
      <span><i class="scope"></i> scope / condition (⊃)</span>
      <span><i class="warning"></i> false friend (≠)</span>
      <span><i class="open"></i> open / conjectured (?)</span>
    </div>
  `;

  config.el.map.innerHTML = renderZooMap(config, selectedNode, selectedEdge);
  config.el.bridgeList.innerHTML = config.edges
    .map((edge) => {
      const from = config.nodeMap[edge.from];
      const to = config.nodeMap[edge.to];
      const edgeId = getZooEdgeId(edge);
      return `
        <button class="zoo-edge-chip zoo-${edge.kind} ${config.selectedEdge === edgeId ? 'is-active' : ''}" data-zoo="${config.id}" data-zoo-edge="${edgeId}">
          <span>${edge.signal}</span>
          <strong>${from.symbol} ${edge.signal} ${to.symbol}</strong>
          <em>${ZOO_RELATION_LABELS[edge.kind] || 'bridge'}</em>
        </button>
      `;
    })
    .join('');

  config.el.detail.innerHTML = selectedEdge ? renderZooRelationDetail(config, selectedEdge) : renderZooNodeDetail(config, selectedNode);
  scheduleBridgeListBalance();
}

function bindZooEvents() {
  document.addEventListener('click', (event) => {
    const edgeButton = event.target.closest('[data-zoo-edge]');
    const nodeButton = event.target.closest('[data-zoo-node]');
    const target = edgeButton || nodeButton;
    if (!target) return;
    const id = target.getAttribute('data-zoo');
    const config = zooRegistry[id];
    if (!config) return;
    if (edgeButton) {
      const edgeId = edgeButton.getAttribute('data-zoo-edge');
      config.selectedEdge = config.selectedEdge === edgeId ? null : edgeId;
    } else {
      config.selectedNodeId = nodeButton.getAttribute('data-zoo-node');
      config.selectedEdge = null;
    }
    renderZooGraphSection(id);
  });
}

