const zooBridges = [
  { kind: 'equivalence', a: 'operators', b: 'trig-complex', shared: `Euler's formula  e^{iθ}`, note: `The Fourier kernel, cis, De Moivre, and the eigenfunctions of d/dx are all the same object.` },
  { kind: 'equivalence', a: 'operators', b: 'fractals', shared: `Power spectrum ↔ spectral dimension`, note: `Two different "spectral" readings. Fourier side: an fBM's power spectrum follows 1/f^β with β = 2H+1 (a PSD-slope fact). Geometry side: on regular fractals the heat-kernel spectral dimension is d_s = 2 d_f / d_w, a return-probability exponent (p_t(x,x) ~ t^{−d_s/2}) needing sub-Gaussian/regular heat-kernel estimates — d_s is not the 1/f^β exponent.` },
  { kind: 'equivalence', a: 'operators', b: 'noise', shared: `Convolution = colored-noise shaping`, note: `Colored noise is white noise through an LSI filter with |H(k)|² = k^{-β}; Wiener–Khinchin pairs autocorrelation with the power spectrum.` },
  { kind: 'equivalence', a: 'fractals', b: 'noise', shared: `Hurst exponent ↔ box dimension`, note: `An fBM graph has dimension D = 2 − H, and the spectral exponent β = 2H+1 feeds the fractal spectral dimension.` },
  { kind: 'consequence', a: 'compactness', b: 'integrals', shared: `Compactness ⟹ integrability`, note: `A continuous function on a compact set is bounded, attains extrema, is uniformly continuous, and is Riemann integrable; Arzelà–Ascoli passes limits under the integral.` },
  { kind: 'consequence', a: 'compactness', b: 'axioms', shared: `Compact + Hausdorff ⟹ normal`, note: `Compactness upgrades separation; compact subsets of Hausdorff spaces are closed.` },
  { kind: 'equivalence', a: 'field-integrals', b: 'spaces', shared: `d² = 0  ↔  ∂² = 0`, note: `The exterior derivative and the homology boundary are dual (de Rham); Stokes pairs chains with cochains, and the Euler characteristic appears in both.` },
  { kind: 'equivalence', a: 'integrals', b: 'operators', shared: `Distributions ↔ Green functions & sampling`, note: `The distributional integral is the framework in which δ-driven Green functions and the Dirac comb are rigorous.` },
  { kind: 'equivalence', a: 'axioms', b: 'counterexamples', shared: `Implication ↔ strictness witness`, note: `Each separation implication is paired with a concrete space proving it cannot be reversed.` },
  { kind: 'equivalence', a: 'ac-equivalents', b: 'compactness', shared: `Tychonoff's theorem`, note: `Arbitrary products of compact spaces are compact iff AC holds (the Hausdorff case is exactly BPI).` },
  { kind: 'equivalence', a: 'ac-equivalents', b: 'induction', shared: `Well-ordering ↔ transfinite induction`, note: `AC well-orders any set, which is what licenses transfinite induction and Zorn's lemma on arbitrary domains.` },
  { kind: 'consequence', a: 'ac-equivalents', b: 'spectral', shared: `Every vector space has a basis`, note: `Equivalent to AC — but this is a Hamel basis of the space, not an eigenbasis of any operator. Basis existence never guarantees one: in infinite dimensions most operators have no eigenbasis (the shift has empty point spectrum), and the spectral theorem replaces eigenvectors with a projection-valued measure, with continuous spectrum generic.` },
  { kind: 'equivalence', a: 'spectral', b: 'operators', shared: `Eigenfunctions diagonalize operators`, note: `The Fourier basis diagonalizes convolution (circulant matrices); shift-invariant operators share the eigenvectors e^{iωx}.` },
  { kind: 'equivalence', a: 'spectral', b: 'noise', shared: `Covariance spectra / PCA`, note: `The spectral theorem diagonalizes covariance matrices; power spectra are densities of eigenvalues.` },
  { kind: 'equivalence', a: 'gauss-bonnet', b: 'spaces', shared: `Total curvature = 2π·χ`, note: `Gauss–Bonnet ties a geometric integral to the Euler characteristic, a purely topological invariant.` },
  { kind: 'equivalence', a: 'gauss-bonnet', b: 'field-integrals', shared: `Stokes' theorem`, note: `Gauss–Bonnet is an integral theorem; curvature integrates against the boundary via Stokes.` },
  { kind: 'equivalence', a: 'gauss-bonnet', b: 'graphics', shared: `Discrete curvature & mesh genus`, note: `Angle defect and discrete Gauss–Bonnet drive remeshing, smoothing, and genus checks.` },
  { kind: 'consequence', a: 'convergence', b: 'integrals', shared: `Dominated / monotone convergence`, note: `The modes of convergence decide exactly when a limit may pass under the integral.` },
  { kind: 'scope', a: 'complexity', b: 'mst', shared: `Greedy / matroid optimality`, note: `The cut/cycle/exchange logic generalizes to matroid greedy — the prototype of an efficient (P-time) algorithm.` },
  { kind: 'equivalence', a: 'galois', b: 'group-theory', shared: `Solvable by radicals ⇔ solvable group`, note: `A polynomial is solvable by radicals iff its Galois group is solvable; the Galois group is itself a group, so the whole zoo runs on group theory.` },
  { kind: 'equivalence', a: 'galois', b: 'category', shared: `Galois connection = adjunction`, note: `The Fundamental Theorem of Galois Theory is an order-reversing bijection of lattices — a Galois connection, the prototypical adjunction.` },
  { kind: 'consequence', a: 'ac-equivalents', b: 'galois', shared: `Zorn ⇒ algebraic closure`, note: `Existence of an algebraic closure and the infinite Galois correspondence (with the Krull topology) need Zorn / the Boolean prime ideal lemma.` },
  { kind: 'consequence', a: 'duality', b: 'complexity', shared: `LP duality + TU ⇒ P`, note: `Strong duality with total unimodularity makes max-flow / bipartite matching poly-time, with complementary slackness as the optimality certificate.` },
  { kind: 'scope', a: 'duality', b: 'mst', shared: `MST = rank-1 matroid case`, note: `MST greedy is the matroid (rank-function) special case of the cut/cycle LP duality the duality zoo abstracts.` },
  { kind: 'scope', a: 'category', b: 'duality', shared: `Categorical duality is the template`, note: `Op-categories, products↔coproducts and mono↔epi are the abstract pattern that LP and max-flow/min-cut duality instantiate.` },
  { kind: 'equivalence', a: 'completeness', b: 'compactness', shared: `Compact = complete + totally bounded`, note: `A metric space is compact iff it is complete and totally bounded — the bridge between the completeness and compactness zoos.` },
  { kind: 'equivalence', a: 'completeness', b: 'convergence', shared: `Complete = Cauchy converges`, note: `Completeness is defined by every Cauchy sequence converging; the convergence modes give L^p completeness (Riesz–Fischer) and the uniform-limit theorem.` },
  { kind: 'equivalence', a: 'completeness', b: 'hilbert-operators', shared: `Hilbert = complete inner-product space`, note: `A Hilbert space is a complete inner-product space, and the Banach fixed-point theorem yields Neumann-series operator inverses.` },
  { kind: 'consequence', a: 'ac-equivalents', b: 'completeness', shared: `Baire ⇐ Dependent Choice`, note: `The Baire category theorem for complete metric spaces is proved using Dependent Choice (DC), an explicit fragment in the choice zoo.` },
  { kind: 'scope', a: 'category', b: 'spectral', shared: `Diagonalization = universal factorization`, note: `An eigenspace decomposition is a direct sum (coproduct) and diagonalization is a universal factorization — spectral theory instantiates category nodes.` },
  { kind: 'scope', a: 'category', b: 'induction', shared: `Induction = initial algebra`, note: `Structural induction and well-founded recursion are initial-algebra (catamorphism) arguments — the categorical view of induction.` },
  { kind: 'equivalence', a: 'gauss-bonnet', b: 'spectral', shared: `Principal curvatures = shape-operator spectrum`, note: `The shape operator is self-adjoint; its eigenvalues are the principal curvatures, with K = det and H = ½ tr — curvature is spectral theory.` },
  { kind: 'scope', a: 'hilbert-operators', b: 'spectral', shared: `Finite-dim is the special case`, note: `The finite-dimensional spectral theorem (matrices) is the special case of the spectral theorem for bounded normal operators.` },
  { kind: 'consequence', a: 'measure-theory', b: 'integrals', shared: `Integral built on the measure`, note: `The Lebesgue integral is defined from the measure: integrate simple functions, then take suprema — measure theory underlies the integral zoo.` },
  { kind: 'consequence', a: 'measure-theory', b: 'convergence', shared: `Modes live on the measure space`, note: `Almost-everywhere, in-measure, and L^p convergence are all defined relative to the underlying measure.` },
  { kind: 'consequence', a: 'measure-theory', b: 'noise', shared: `Processes need a probability space`, note: `A stochastic process is a measurable map on a probability (measure) space; fBM and colored noise presuppose the measure-theory foundations.` },
  { kind: 'equivalence', a: 'hilbert-operators', b: 'operators', shared: `Fourier = unitary on L²`, note: `The Fourier transform is a unitary operator (Plancherel) and the complex exponentials are an orthonormal basis of L².` },
  { kind: 'consequence', a: 'ac-equivalents', b: 'group-theory', shared: `Zorn ⇒ maximal subgroups`, note: `Existence of maximal subgroups and several infinite-group constructions invoke Zorn’s lemma.` },
  { kind: 'consequence', a: 'ac-equivalents', b: 'measure-theory', shared: `AC ⇒ non-measurable sets`, note: `Non-measurable sets (the Vitali set) exist precisely because of the Axiom of Choice — without it, all sets can be Lebesgue measurable.` },
  { kind: 'consequence', a: 'noise', b: 'graphics', shared: `Procedural noise → texture & terrain`, note: `Value/Perlin/simplex noise and fractional Brownian surfaces synthesize textures, terrain, and surface detail.` },
  { kind: 'consequence', a: 'spectral', b: 'graphics', shared: `Spectral mesh processing`, note: `SVD/eigendecomposition powers mesh compression, spectral smoothing, PCA shape spaces, and deformation transfer.` },
  { kind: 'consequence', a: 'fractals', b: 'graphics', shared: `Fractal detail synthesis`, note: `Self-similar subdivision and fractal dimension drive terrain generation and controllable surface roughness.` },
  { kind: 'scope', a: 'atlas', b: 'compactness', shared: `Point-set core`, note: `The atlas’s point-set entries — compactness, separation, convergence — are formalized as the compactness equivalence web.` },
  { kind: 'scope', a: 'atlas', b: 'spaces', shared: `Spaces & invariants`, note: `The atlas’s algebraic-topology entries (π₁, homology, genus, Euler characteristic) are compared in the invariant explorer.` },
  { kind: 'equivalence', a: 'galois', b: 'number-theory', shared: `Finite fields & Frobenius`, note: `F_p = Z/p; the Frobenius x↦x^p generates the Galois group of a finite field, and quadratic reciprocity reflects splitting in cyclotomic fields.` },
  { kind: 'consequence', a: 'group-theory', b: 'number-theory', shared: `Lagrange ⇒ Fermat/Euler`, note: `Fermat and Euler are Lagrange’s theorem applied to the unit group (Z/n)^*; a primitive root exists iff that group is cyclic.` },
  { kind: 'scope', a: 'convexity', b: 'duality', shared: `LP duality is the polyhedral case`, note: `Linear-programming and max-flow/min-cut duality are the polyhedral special case of Lagrangian / Fenchel convex duality.` },
  { kind: 'equivalence', a: 'convexity', b: 'hilbert-operators', shared: `Projection onto convex sets`, note: `In a Hilbert space the nearest point in a closed convex set exists and is unique (the projection theorem) — a convex-analytic backbone of Riesz and least squares.` },
  { kind: 'consequence', a: 'ac-equivalents', b: 'convexity', shared: `Hahn-Banach ⇐ BPI`, note: `The Hahn-Banach theorem follows from the Boolean prime ideal lemma — strictly weaker than full AC, yet still independent of ZF.` },
  { kind: 'consequence', a: 'number-theory', b: 'complexity', shared: `Primality & factoring`, note: `The Fermat/Miller-Rabin tests give randomized primality (RP/coRP), while the presumed hardness of factoring underpins public-key cryptography.` },
];

function labelForZoo(id) {
  const meta = zooMeta.find((zoo) => zoo.id === id);
  if (meta) return meta.label;
  return ({ graphics: 'Graphics processing', atlas: 'Concept atlas', concepts: 'Concept atlas' })[id] || id;
}

function renderBridgesSection() {
  const grid = document.getElementById('bridgesGrid');
  if (!grid) return;
  grid.innerHTML = zooBridges
    .map(
      (bridge) => `
        <article class="bridge-card bridge-${bridge.kind || 'equivalence'}">
          <div class="bridge-card-zoos">
            <a href="#${bridge.a}">${labelForZoo(bridge.a)}</a>
            <span class="bridge-link">${({ equivalence: '⟷', consequence: '⟶', scope: '⊃' })[bridge.kind] || '⟷'}</span>
            <a href="#${bridge.b}">${labelForZoo(bridge.b)}</a>
          </div>
          <strong class="bridge-shared">${bridge.shared}</strong>
          <p>${bridge.note}</p>
        </article>
      `
    )
    .join('');
}

function injectBridgeHints() {
  const byZoo = {};
  zooBridges.forEach((bridge) => {
    (byZoo[bridge.a] = byZoo[bridge.a] || []).push(bridge.b);
    (byZoo[bridge.b] = byZoo[bridge.b] || []).push(bridge.a);
  });
  Object.keys(byZoo).forEach((id) => {
    const section = document.getElementById(id);
    if (!section) return;
    const heading = section.querySelector('.section-heading');
    if (!heading || heading.querySelector('.zoo-bridge-hints')) return;
    const others = [...new Set(byZoo[id])];
    const row = document.createElement('div');
    row.className = 'zoo-bridge-hints';
    row.innerHTML =
      `<span>Bridges to</span>` +
      others.map((other) => `<a href="#${other}">${labelForZoo(other)}</a>`).join('') +
      `<a class="bridge-hint-map" href="#bridges">all bridges →</a>`;
    heading.appendChild(row);
  });
}

// Persistent section navigator: a fixed dock of dots (one per section, grouped
// like the nav), always visible, with hover labels, click-to-jump, and a
// scroll-spy that highlights the section currently in view.
function buildSectionDock() {
  const groups = document.querySelectorAll('.topbar-links .nav-group');
  if (!groups.length || document.querySelector('.section-dock')) return;
  const dock = document.createElement('nav');
  dock.className = 'section-dock';
  dock.setAttribute('aria-label', 'Section navigator');
  const items = [];
  groups.forEach((group) => {
    const g = document.createElement('div');
    g.className = 'section-dock-group';
    const labelEl = group.querySelector('.nav-group-label');
    const groupLabel = labelEl ? labelEl.textContent : '';
    group.querySelectorAll('a[href^="#"]').forEach((a) => {
      const id = a.getAttribute('href').slice(1);
      const section = document.getElementById(id);
      // Skip sections that are absent or hidden (e.g. a roadmap with no content yet).
      if (!section || section.hidden) return;
      const item = document.createElement('a');
      item.className = 'section-dock-item';
      item.href = '#' + id;
      const accent = getComputedStyle(section).getPropertyValue('--section-accent').trim();
      if (accent) item.style.setProperty('--dot', accent);
      const label = a.textContent.trim();
      item.setAttribute('aria-label', label);
      item.innerHTML = `<span class="section-dock-dot"></span><span class="section-dock-label">${label}</span>`;
      g.appendChild(item);
      items.push({ id, item });
    });
    dock.appendChild(g);
  });
  document.body.appendChild(dock);

  const updateActive = () => {
    const probe = window.innerHeight * 0.3;
    let current = items[0];
    items.forEach((it) => {
      const section = document.getElementById(it.id);
      if (section && section.getBoundingClientRect().top <= probe) current = it;
    });
    items.forEach((it) => it.item.classList.toggle('is-active', it === current));
  };
  let ticking = false;
  window.addEventListener(
    'scroll',
    () => {
      if (!ticking) {
        ticking = true;
        requestAnimationFrame(() => {
          updateActive();
          ticking = false;
        });
      }
    },
    { passive: true }
  );
  updateActive();
}

function initZoos() {
  NEW_ZOO_DATA.forEach((data) => defineZooGraph(data));
  Object.keys(zooRegistry).forEach((id) => renderZooGraphSection(id));
  renderBridgesSection();
  injectBridgeHints();
}

