// Hand-drawn inline SVG for the few ideas where a picture carries the argument
// better than prose. This is MARKUP, so it deliberately lives outside the data
// arrays that sanitizeDataStrings() escapes.
const FIG_ARROW_DEFS =
  '<defs><marker id="figHead" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse">' +
  '<path d="M0 0 L10 5 L0 10 z" fill="var(--section-accent)"/></marker></defs>';

function figCoverBars(x0, x1, rows, on) {
  const bars = [];
  const span = x1 - x0;
  for (let i = 0; i < 9; i += 1) {
    const a = x0 + (span / 10) * i;
    const b = Math.min(x1, a + span / 4);
    bars.push(
      `<line class="fig-bar" x1="${a.toFixed(1)}" y1="${rows[i % 3]}" x2="${b.toFixed(1)}" y2="${rows[i % 3]}"/>`
    );
  }
  return on ? '' : bars.join('');
}

