// Figures sit directly under the section heading, so the picture frames the
// section before the reader meets the graph.
function renderSectionFigures() {
  Object.keys(SECTION_FIGURES).forEach((id) => {
    const section = document.getElementById(id);
    if (!section || section.querySelector('.section-figure')) return;
    const heading = section.querySelector('.section-heading');
    if (!heading) return;
    const fig = document.createElement('figure');
    fig.className = 'section-figure';
    const { svg, caption } = SECTION_FIGURES[id];
    fig.innerHTML = `${svg}<figcaption>${caption}</figcaption>`;
    heading.insertAdjacentElement('afterend', fig);
  });
}

