let algoMap = {};

function renderAlgorithmsSection() {
  const listEl = document.getElementById('algoList');
  const detailEl = document.getElementById('algoDetail');
  const noteEl = document.getElementById('algoNote');
  if (!listEl || !detailEl) return;
  if (noteEl) {
    noteEl.innerHTML = `
      <p><strong>Read it:</strong> each card is a technique cluster — the core idea, when to reach for it, the pattern, canonical LeetCode problems, and the math zoo that grounds it. Click a problem-type to see the playbook; follow the theory links to the proof that explains why it works.</p>
      <div class="algo-tier-legend">${ALGO_TIERS.map((t) => `<span>${t.label}</span>`).join('')}</div>
    `;
  }
  const selected = algoMap[state.selectedAlgoId] || ALGO_CLUSTERS[0];
  if (!selected) { listEl.innerHTML = ''; detailEl.innerHTML = ''; return; }
  state.selectedAlgoId = selected.id;

  listEl.innerHTML = ALGO_TIERS.map((tier) => {
    const items = ALGO_CLUSTERS.filter((c) => c.tier === tier.id);
    if (!items.length) return '';
    return `
      <div class="algo-tier">
        <h3 class="algo-tier-head">${tier.label}</h3>
        <div class="algo-cards">
          ${items
            .map(
              (c) => `
                <button class="algo-card ${c.id === selected.id ? 'is-active' : ''}" data-algo="${c.id}">
                  <span class="algo-card-sym">${c.symbol}</span>
                  <strong>${c.title}</strong>
                  <em>${c.problems.length} problems${c.variants && c.variants.length ? ' &middot; ' + c.variants.length + ' patterns' : ''}</em>
                </button>
              `
            )
            .join('')}
        </div>
      </div>
    `;
  }).join('');

  detailEl.innerHTML = renderAlgoDetail(selected);
  scheduleBridgeListBalance();
}

function renderAlgoDetail(c) {
  const tierLabel = (ALGO_TIERS.find((t) => t.id === c.tier) || {}).label || c.tier;
  const diffClass = { Easy: 'algo-easy', Medium: 'algo-medium', Hard: 'algo-hard' };
  return `
    <div class="detail-badges">
      ${renderBadge(tierLabel, 'zoo-tag')}
      ${renderBadge(c.problems.length + ' problems', 'zoo-tag')}
      ${c.variants && c.variants.length ? renderBadge(c.variants.length + ' sub-patterns', 'zoo-tag') : ''}
    </div>
    <h2 class="detail-title trig-title-with-symbol"><span class="algo-symbol">${c.symbol}</span>${c.title}</h2>
    <div class="detail-block"><h3>Core idea</h3><p>${c.idea}</p></div>
    <div class="detail-block"><h3>When to reach for it</h3><p>${c.whenToUse}</p></div>
    <div class="algo-pattern"><span>pattern</span><pre>${c.pattern}</pre></div>
    <div class="algo-meta-grid">
      <article><span>complexity</span><p>${c.complexity}</p></article>
      <article><span>pitfalls</span><p>${c.pitfalls}</p></article>
    </div>
    ${
      c.variants && c.variants.length
        ? `<section class="algo-variants">
            <h3>Sub-patterns <span class="algo-count">${c.variants.length}</span></h3>
            <div class="algo-variant-list">
              ${c.variants
                .map(
                  (v) => `
                    <article class="algo-variant">
                      <h4>${v.name}</h4>
                      <p>${v.gist}</p>
                      <div class="algo-vprobs">${v.problems
                        .map((p) => `<span class="algo-vprob ${diffClass[p.difficulty] || ''}" title="${p.difficulty}">${p.name}</span>`)
                        .join('')}</div>
                    </article>`
                )
                .join('')}
            </div>
          </section>`
        : ''
    }
    <section class="algo-problems">
      <h3>Canonical problems</h3>
      <ul>
        ${c.problems
          .map(
            (p) => `<li><span class="algo-diff ${diffClass[p.difficulty] || ''}">${p.difficulty}</span><strong>${p.name}</strong><em>${p.note}</em></li>`
          )
          .join('')}
      </ul>
    </section>
    ${
      c.prereqs && c.prereqs.length
        ? `<section class="algo-links"><h3>Build on</h3><div>${c.prereqs
            .map((id) => (algoMap[id] ? `<button class="algo-chip" data-algo="${id}">${algoMap[id].title}</button>` : ''))
            .join('')}</div></section>`
        : ''
    }
    ${
      c.theoryLinks && c.theoryLinks.length
        ? `<section class="algo-links"><h3>Grounded in</h3><div>${c.theoryLinks
            .map((t) => `<a class="algo-chip algo-theory" href="#${t.zoo}" title="${t.note}">${labelForZoo(t.zoo)}</a>`)
            .join('')}</div></section>`
        : ''
    }
  `;
}

function escapeHtml(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

// Authored content is TEXT, never markup, but it is full of mathematics: "H<G",
// "<S>", "p<infty", "pi_1 = <a,b | R>". Interpolated raw into a template those
// open real elements — "<S>" became an <s> tag that struck through the rest of
// the page, and "H<G" swallowed its own card's title. Escape every string in a
// data set once, in place, before anything renders it.
function sanitizeDataStrings(value) {
  if (Array.isArray(value)) {
    for (let i = 0; i < value.length; i += 1) {
      if (typeof value[i] === 'string') value[i] = escapeHtml(value[i]);
      else sanitizeDataStrings(value[i]);
    }
  } else if (value && typeof value === 'object') {
    Object.keys(value).forEach((key) => {
      if (typeof value[key] === 'string') value[key] = escapeHtml(value[key]);
      else sanitizeDataStrings(value[key]);
    });
  }
  return value;
}

function bindAlgoEvents() {
  const section = document.getElementById('algorithms');
  if (!section) return;
  section.addEventListener('click', (event) => {
    const btn = event.target.closest('[data-algo]');
    if (!btn) return;
    const id = btn.getAttribute('data-algo');
    if (!algoMap[id]) return;
    state.selectedAlgoId = id;
    renderAlgorithmsSection();
    const d = document.getElementById('algoDetail');
    if (d) d.scrollIntoView({ block: 'nearest' });
  });
}

function initAlgorithms() {
  sanitizeDataStrings(ALGO_CLUSTERS);
  algoMap = Object.fromEntries(ALGO_CLUSTERS.map((c) => [c.id, c]));
  state.selectedAlgoId = ALGO_CLUSTERS[0] ? ALGO_CLUSTERS[0].id : null;
  renderAlgorithmsSection();
  bindAlgoEvents();
}

initAlgorithms();

