let hcMap = {};

function renderHypercomplexSection() {
  const listEl = document.getElementById('hcList');
  const detailEl = document.getElementById('hcDetail');
  const noteEl = document.getElementById('hcNote');
  if (!listEl || !detailEl) return;
  if (noteEl) {
    noteEl.innerHTML = `
      <p><strong>Read it:</strong> one ladder of number systems built for rotation and geometry &mdash; ℝ → ℂ → ℍ → \u{1D546}, and the Clifford/geometric algebra that unifies them. Each card carries the core idea, the geometric intuition, the defining identities, sub-topics, applications, and links to the theory zoos.</p>
      <div class="algo-tier-legend">${HC_TIERS.map((t) => `<span>${t.label}</span>`).join('')}</div>
    `;
  }
  const selected = hcMap[state.selectedHcId] || HC_CLUSTERS[0];
  if (!selected) { listEl.innerHTML = ''; detailEl.innerHTML = ''; return; }
  state.selectedHcId = selected.id;

  listEl.innerHTML = HC_TIERS.map((tier) => {
    const items = HC_CLUSTERS.filter((c) => c.tier === tier.id);
    if (!items.length) return '';
    return `
      <div class="algo-tier">
        <h3 class="algo-tier-head">${tier.label}</h3>
        <div class="algo-cards">
          ${items
            .map(
              (c) => `
                <button class="algo-card ${c.id === selected.id ? 'is-active' : ''}" data-hc="${c.id}">
                  <span class="algo-card-sym">${c.symbol}</span>
                  <strong>${c.title}</strong>
                  <em>${c.variants.length} sub-topics</em>
                </button>
              `
            )
            .join('')}
        </div>
      </div>
    `;
  }).join('');

  detailEl.innerHTML = renderHcDetail(selected);
  scheduleBridgeListBalance();
}

function renderHcDetail(c) {
  const tierLabel = (HC_TIERS.find((t) => t.id === c.tier) || {}).label || c.tier;
  return `
    <div class="detail-badges">
      ${renderBadge(tierLabel, 'zoo-tag')}
      ${renderBadge(c.variants.length + ' sub-topics', 'zoo-tag')}
    </div>
    <h2 class="detail-title trig-title-with-symbol"><span class="algo-symbol">${c.symbol}</span>${c.title}</h2>
    <div class="detail-block"><h3>What it is</h3><p>${c.idea}</p></div>
    <div class="detail-block"><h3>Intuition</h3><p>${c.intuition}</p></div>
    <div class="algo-pattern"><span>key identities</span><pre>${c.keyFacts}</pre></div>
    <div class="detail-block"><h3>Where it shows up</h3><p>${c.applications}</p></div>
    <section class="algo-variants">
      <h3>Sub-topics <span class="algo-count">${c.variants.length}</span></h3>
      <div class="algo-variant-list">
        ${c.variants
          .map(
            (v) => `
              <article class="algo-variant">
                <h4>${v.name}</h4>
                <p>${v.gist}</p>
                <div class="algo-vprobs">${v.examples.map((e) => `<span class="algo-vprob">${e}</span>`).join('')}</div>
              </article>`
          )
          .join('')}
      </div>
    </section>
    ${
      c.prereqs && c.prereqs.length
        ? `<section class="algo-links"><h3>Build on</h3><div>${c.prereqs
            .map((id) => (hcMap[id] ? `<button class="algo-chip" data-hc="${id}">${hcMap[id].title}</button>` : ''))
            .join('')}</div></section>`
        : ''
    }
    ${
      c.links && c.links.length
        ? `<section class="algo-links"><h3>Connections</h3><div>${c.links
            .map((t) => `<a class="algo-chip algo-theory" href="#${t.zoo}" title="${t.note}">${labelForZoo(t.zoo)}</a>`)
            .join('')}</div></section>`
        : ''
    }
  `;
}

function bindHcEvents() {
  const section = document.getElementById('hypercomplex');
  if (!section) return;
  section.addEventListener('click', (event) => {
    const btn = event.target.closest('[data-hc]');
    if (!btn) return;
    const id = btn.getAttribute('data-hc');
    if (!hcMap[id]) return;
    state.selectedHcId = id;
    renderHypercomplexSection();
    const d = document.getElementById('hcDetail');
    if (d) d.scrollIntoView({ block: 'nearest' });
  });
}

function initHypercomplex() {
  sanitizeDataStrings(HC_CLUSTERS);
  hcMap = Object.fromEntries(HC_CLUSTERS.map((c) => [c.id, c]));
  state.selectedHcId = HC_CLUSTERS[0] ? HC_CLUSTERS[0].id : null;
  renderHypercomplexSection();
  bindHcEvents();
}

initHypercomplex();

