function renderConceptRoadmap(cfg) {
  const listEl = document.getElementById(cfg.listId);
  const detailEl = document.getElementById(cfg.detailId);
  const noteEl = document.getElementById(cfg.noteId);
  if (!listEl || !detailEl) return;
  // A roadmap with no topics authored yet is hidden entirely, along with its nav
  // link, so the page never shows an empty section.
  const sectionEl = document.getElementById(cfg.sectionId);
  if (!cfg.clusters.length) {
    if (sectionEl) sectionEl.hidden = true;
    const navLink = document.querySelector(`.topbar-links a[href="#${cfg.sectionId}"]`);
    if (navLink) navLink.hidden = true;
    return;
  }
  if (sectionEl) sectionEl.hidden = false;
  if (noteEl) {
    noteEl.innerHTML = `
      <p><strong>Read it:</strong> ${cfg.intro}</p>
      <div class="algo-tier-legend">${cfg.tiers.map((t) => `<span>${t.label}</span>`).join('')}</div>
    `;
  }
  const selected = cfg.map[state[cfg.stateKey]] || cfg.clusters[0];
  if (!selected) { listEl.innerHTML = ''; detailEl.innerHTML = ''; return; }
  state[cfg.stateKey] = selected.id;

  listEl.innerHTML = cfg.tiers.map((tier) => {
    const items = cfg.clusters.filter((c) => c.tier === tier.id);
    if (!items.length) return '';
    return `
      <div class="algo-tier">
        <h3 class="algo-tier-head">${tier.label}</h3>
        <div class="algo-cards">
          ${items
            .map(
              (c) => `
                <button class="algo-card ${c.id === selected.id ? 'is-active' : ''}" data-concept="${cfg.key}" data-id="${c.id}">
                  <span class="algo-card-sym">${c.symbol}</span>
                  <strong>${c.title}</strong>
                  <em>${c.variants.length} sub-topics</em>
                </button>
              `
            )
            .join('')}
        </div>
      </div>
    `;
  }).join('');

  detailEl.innerHTML = renderRoadmapDetail(selected, cfg);
  scheduleBridgeListBalance();
}

function renderRoadmapDetail(c, cfg) {
  const tierLabel = (cfg.tiers.find((t) => t.id === c.tier) || {}).label || c.tier;
  return `
    <div class="detail-badges">
      ${renderBadge(tierLabel, 'zoo-tag')}
      ${renderBadge(c.variants.length + ' sub-topics', 'zoo-tag')}
    </div>
    <h2 class="detail-title trig-title-with-symbol"><span class="algo-symbol">${c.symbol}</span>${c.title}</h2>
    <div class="detail-block"><h3>What it is</h3><p>${c.idea}</p></div>
    <div class="detail-block"><h3>Intuition</h3><p>${c.intuition}</p></div>
    <div class="algo-pattern"><span>key facts</span><pre>${c.keyFacts}</pre></div>
    <div class="detail-block"><h3>Where it shows up</h3><p>${c.applications}</p></div>
    <section class="algo-variants">
      <h3>Sub-topics <span class="algo-count">${c.variants.length}</span></h3>
      <div class="algo-variant-list">
        ${c.variants
          .map(
            (v) => `
              <article class="algo-variant">
                <h4>${v.name}</h4>
                <p>${v.gist}</p>
                <div class="algo-vprobs">${v.examples.map((e) => `<span class="algo-vprob">${e}</span>`).join('')}</div>
              </article>`
          )
          .join('')}
      </div>
    </section>
    ${
      c.prereqs && c.prereqs.length
        ? `<section class="algo-links"><h3>Build on</h3><div>${c.prereqs
            .map((id) => (cfg.map[id] ? `<button class="algo-chip" data-concept="${cfg.key}" data-id="${id}">${cfg.map[id].title}</button>` : ''))
            .join('')}</div></section>`
        : ''
    }
    ${
      c.links && c.links.length
        ? `<section class="algo-links"><h3>Connections</h3><div>${c.links
            .map((t) => `<a class="algo-chip algo-theory" href="#${t.zoo}" title="${t.note}">${labelForZoo(t.zoo)}</a>`)
            .join('')}</div></section>`
        : ''
    }
  `;
}

