function bindConceptRoadmaps() {
  CONCEPT_ROADMAPS.forEach((cfg) => {
    const section = document.getElementById(cfg.sectionId);
    if (!section) return;
    section.addEventListener('click', (event) => {
      const btn = event.target.closest(`[data-concept="${cfg.key}"]`);
      if (!btn) return;
      const id = btn.getAttribute('data-id');
      if (!cfg.map[id]) return;
      state[cfg.stateKey] = id;
      renderConceptRoadmap(cfg);
      const d = document.getElementById(cfg.detailId);
      if (d) d.scrollIntoView({ block: 'nearest' });
    });
  });
}

function initConceptRoadmaps() {
  CONCEPT_ROADMAPS.forEach((cfg) => {
    sanitizeDataStrings(cfg.clusters);
    cfg.map = Object.fromEntries(cfg.clusters.map((c) => [c.id, c]));
    state[cfg.stateKey] = cfg.clusters[0] ? cfg.clusters[0].id : null;
    renderConceptRoadmap(cfg);
  });
  bindConceptRoadmaps();
}

initConceptRoadmaps();

// Built last, so it can skip roadmap sections that have no content yet.
buildSectionDock();
